package com.cabbingo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The button that opens and closes the board window (BoardOverlay). A plain RuneLite overlay: Alt-drag moves it and
 * RuneLite keeps where. Shown while the team has a board, unless turned off in the config. Drawn under the game's
 * interfaces: one over it gets the clicks (covered). The plugin adds "Open Bingo board" to its right-click menu; with
 * "Open board on right-click only" a left click goes through it to the game.
 */
@Singleton
class BoardButton extends Overlay
{
	private final BoardOverlay board;
	private final ItemManager itemManager;
	private final CabbingoConfig config;
	private BufferedImage icon;
	private ButtonIcon iconOf; // the config's icon that icon was loaded for
	private BufferedImage iconMine; // the own picture icon was taken from (null: an item)
	volatile BufferedImage own; // the icons folder's picture (CabbingoPlugin.loadIcon, off the client thread); null: none there
	private Rectangle drawn; // the icon's own pixels in its picture (the picture has room around it); null until loaded
	volatile boolean covered; // a game interface lies over it (the plugin's menu check)
	private boolean ownPress; // the last press was taken here: its release and click are too, no other

	@Inject
	BoardButton(BoardOverlay board, ItemManager itemManager, CabbingoConfig config)
	{
		this.board = board;
		this.itemManager = itemManager;
		this.config = config;
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!board.hasBoard() || !config.boardButton())
		{
			return null;
		}
		int size = config.buttonSize().px;
		ButtonIcon want = config.buttonIcon();
		BufferedImage mine = want == ButtonIcon.FOLDER ? own : null;
		if (icon == null || iconOf != want || iconMine != mine)
		{
			// the icons folder's picture, else the item (a cabbage while the folder has none)
			iconOf = want;
			iconMine = mine;
			icon = mine != null ? mine : itemManager.getImage(want.itemId > 0 ? want.itemId : ButtonIcon.CABBAGE.itemId);
			drawn = null;
		}
		g.setColor(config.background());
		g.fillRect(0, 0, size, size);
		if (!frame(g, size))
		{
			g.setColor(new Color(30, 25, 20));
			g.drawRect(0, 0, size - 1, size - 1);
			g.setColor(new Color(90, 80, 64));
			g.drawRect(1, 1, size - 3, size - 3);
		}
		if (drawn == null)
		{
			drawn = opaque(icon);
		}
		Rectangle c = drawn == null ? new Rectangle(icon.getWidth(), icon.getHeight()) : drawn;
		// a game sprite: fitted at the largest of the board's sprite steps that fits, so it stays pixel-sharp; an own
		// picture is no sprite: smoothly fitted in the frame
		double room = Math.min((size - 8.0) / c.width, (size - 8.0) / c.height);
		double f = mine != null ? room : fit(room);
		int w = (int) Math.round(c.width * f), h = (int) Math.round(c.height * f);
		Object hint = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, mine != null
			? RenderingHints.VALUE_INTERPOLATION_BICUBIC : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(icon, (size - w) / 2, (size - h) / 2, (size - w) / 2 + w, (size - h) / 2 + h, c.x, c.y, c.x + c.width, c.y + c.height, null);
		if (hint != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, hint);
		}
		return new Dimension(size, size);
	}

	// the largest step (2x, 1x, 0.75x, 0.5x) at most room; under 0.5x room itself
	static double fit(double room)
	{
		for (double s : new double[]{2, 1, 0.75, 0.5})
		{
			if (s <= room)
			{
				return s;
			}
		}
		return room;
	}

	// The game's stone button frame (or a resource pack's): corners as they are, the edges stretched between them, each
	// cut to its visible pixels as the board's border is (BoardOverlay.trim), so the frame reaches the button's edge and
	// no background shows around it (user, 2026-11-21). False while the game has not got the sprites.
	private boolean frame(Graphics2D g, int size)
	{
		BufferedImage tl = stone(SpriteID.V2StoneButton.TOP_LEFT), tr = stone(SpriteID.V2StoneButton.TOP_RIGHT),
			bl = stone(SpriteID.V2StoneButton.BOTTOM_LEFT), br = stone(SpriteID.V2StoneButton.BOTTOM_RIGHT),
			l = stone(SpriteID.V2StoneButton.LEFT), t = stone(SpriteID.V2StoneButton.TOP),
			r = stone(SpriteID.V2StoneButton.RIGHT), b = stone(SpriteID.V2StoneButton.BOTTOM);
		if (tl == null || tr == null || bl == null || br == null || l == null || t == null || r == null || b == null)
		{
			return false;
		}
		g.drawImage(t, tl.getWidth(), 0, size - tl.getWidth() - tr.getWidth(), t.getHeight(), null);
		g.drawImage(b, bl.getWidth(), size - b.getHeight(), size - bl.getWidth() - br.getWidth(), b.getHeight(), null);
		g.drawImage(l, 0, tl.getHeight(), l.getWidth(), size - tl.getHeight() - bl.getHeight(), null);
		g.drawImage(r, size - r.getWidth(), tr.getHeight(), r.getWidth(), size - tr.getHeight() - br.getHeight(), null);
		g.drawImage(tl, 0, 0, null);
		g.drawImage(tr, size - tr.getWidth(), 0, null);
		g.drawImage(bl, 0, size - bl.getHeight(), null);
		g.drawImage(br, size - br.getWidth(), size - br.getHeight(), null);
		return true;
	}

	private BufferedImage stone(int id)
	{
		return board.trim(board.sprite(id));
	}

	// The box around a picture's visible pixels; null while it is all clear (an item picture that is still loading)
	static Rectangle opaque(BufferedImage img)
	{
		Rectangle box = null;
		for (int py = 0; py < img.getHeight(); py++)
		{
			for (int px = 0; px < img.getWidth(); px++)
			{
				if ((img.getRGB(px, py) >>> 24) != 0)
				{
					if (box == null)
					{
						box = new Rectangle(px, py, 1, 1);
					}
					else
					{
						box.add(new Rectangle(px, py, 1, 1));
					}
				}
			}
		}
		return box;
	}

	// the button is shown here and not under an interface
	boolean hovered(int px, int py)
	{
		return board.hasBoard() && config.boardButton() && !covered && getBounds().contains(px, py);
	}

	// the button's clicks (the plugin registers it)
	final MouseAdapter mouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			// only a left click, and not with right-click only: a right click opens the menu, the middle button turns the camera
			ownPress = hovered(e.getX(), e.getY()) && !config.boardRightClick() && !e.isAltDown() && SwingUtilities.isLeftMouseButton(e);
			if (ownPress)
			{
				board.toggle();
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			if (ownPress && SwingUtilities.isLeftMouseButton(e))
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			if (ownPress && SwingUtilities.isLeftMouseButton(e))
			{
				e.consume();
			}
			return e;
		}
	};
}

