/**
 * Sends every kill, PvP kill and pet of a bingo player to their Cabbingo team. The server counts it for the
 * team's gp lists and its tiles, and passes it on to the team's Discord channel. A screenshot goes along only
 * when it matters: a tile's item, a pet, a big drop, or a drop a tile counts the value of.
 *
 * The parts: Team (the server's copy of the team, the live line), Sender (posts), Popups (finished tiles), Kills,
 * Skilling, Gear (rules and the random event infobox), and the board window (BoardOverlay, BoardButton).
 */
@Slf4j
@PluginDescriptor(
	name = "Cabbingo",
	internalName = "cabbingo", // the Plugin Hub's name: plugin-data/cabbingo is the plugin's own folder
	description = "Sends your bingo drops, kills and pets to your Cabbingo team",
	tags = {"bingo", "clan", "loot", "discord"}
)
public class CabbingoPlugin extends Plugin
{
	private static final Set<String> SOUND_KEYS = Set.of("sound", "flipSound", "volume", "test", "testFlip");
	private static final Set<String> FOLLOW_KEYS = Set.of("followPicked", "followActive", "tilePanel", "tileInfoBox");
	private static final Pattern ICON_FILE = Pattern.compile("(?i).+[.](png|jpe?g|gif)$");
	private static final long MAX_ICON_PIXELS = 2048 * 2048; // 16 MB in memory at most, before it is made 64 px
	// worlds whose XP is not on the normal hiscores: no TempleOSRS update from them
	private static final Set<WorldType> OFF_HISCORES = EnumSet.of(WorldType.SEASONAL, WorldType.DEADMAN, WorldType.BETA_WORLD,
		WorldType.TOURNAMENT_WORLD, WorldType.NOSAVE_MODE, WorldType.FRESH_START_WORLD, WorldType.QUEST_SPEEDRUNNING);

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;
	@Inject private EventBus eventBus;
	@Inject private OkHttpClient http;
	@Inject private OverlayManager overlayManager;
	@Inject private MouseManager mouseManager;
	@Inject private KeyManager keyManager;
	@Inject private CabbingoConfig config;
	@Inject private Team team;
	@Inject private Sender sender;
	@Inject private Popups popups;
	@Inject private Kills kills;
	@Inject private Skilling skilling;
	@Inject private Gear gear;
	// the board window and its button (2026-11-12)
	@Inject private BoardOverlay boardOverlay;
	@Inject private BoardButton boardButton;
	@Inject private TilePanel tilePanel;
	@Inject private ScheduledExecutorService executor;
	// the self-hosted bingo's side panel (SelfPanel, 2026-11-14)
	@Inject private Injector injector;
	@Inject private ClientToolbar clientToolbar;
	private SelfPanel selfPanel;
	private NavigationButton selfButton;
	private boolean selfShown;

	// For the TempleOSRS update on logout: who played and their total XP when the session started (-1: none yet).
	private String templeName;
	private long templeXp = -1;

	@Override
	protected void startUp()
	{
		popups.start();
		team.onWants(this::apply);
		eventBus.register(kills);
		eventBus.register(skilling);
		overlayManager.add(boardOverlay);
		overlayManager.add(boardButton);
		overlayManager.add(tilePanel);
		mouseManager.registerMouseListener(boardOverlay);
		mouseManager.registerMouseWheelListener(boardOverlay);
		mouseManager.registerMouseListener(boardButton.mouse);
		keyManager.registerKeyListener(boardOverlay);
		executor.execute(this::loadIcon); // (makes the icons folder too)
		team.fetch();
		SwingUtilities.invokeLater(() ->
		{
			selfPanel = injector.getInstance(SelfPanel.class);
			selfButton = NavigationButton.builder().tooltip("Cabbingo bingo").icon(SelfPanel.icon()).priority(8).panel(selfPanel).build();
			sidebar();
		});
	}

	// The player's own button picture from plugin-data/cabbingo/icons (made here, so it is there to put pictures in): the
	// file named in the config, else the first picture by name. Read off the client thread; none: the button's item.
	private void loadIcon()
	{
		BufferedImage img = null;
		try
		{
			Filepath dir = getPluginDirectory().joinSegment("icons");
			dir.createDirectories();
			if (config.buttonIcon() == ButtonIcon.FOLDER)
			{
				String want = config.buttonIconFile().trim();
				Filepath file;
				try (Stream<Filepath> all = dir.walk(1))
				{
					file = all.filter(f -> f.isFile() && ICON_FILE.matcher(f.getFileName()).matches()
							&& (want.isEmpty() || f.getFileName().equalsIgnoreCase(want)
								|| f.getFileName().replaceFirst("[.][^.]*$", "").equalsIgnoreCase(want))) // "image" finds image.png
						.min(Comparator.comparing(Filepath::getFileName)).orElse(null);
				}
				if (file != null && file.size() <= 2_000_000)
				{
					try (InputStream in = file.openInputStream(); ImageInputStream iis = ImageIO.createImageInputStream(in))
					{
						Iterator<ImageReader> readers = iis == null ? Collections.emptyIterator() : ImageIO.getImageReaders(iis);
						ImageReader reader = readers.hasNext() ? readers.next() : null;
						if (reader != null)
						{
							try
							{
								reader.setInput(iis, true, true);
								// the size from the header first: a small file can still be a huge picture in memory
								if ((long) reader.getWidth(0) * reader.getHeight(0) <= MAX_ICON_PIXELS)
								{
									img = reader.read(0);
								}
							}
							finally
							{
								reader.dispose();
							}
						}
					}
				}
			}
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Cabbingo: button icon not read", ex);
		}
		// at most 64 px: Java holds a picture at full size in memory (AGENTS.md)
		if (img != null && Math.max(img.getWidth(), img.getHeight()) > 64)
		{
			int most = Math.max(img.getWidth(), img.getHeight());
			img = ImageUtil.resizeImage(img, Math.max(1, img.getWidth() * 64 / most), Math.max(1, img.getHeight() * 64 / most));
		}
		boardButton.own = img;
	}

	// The side panel: for an owner who turned it on, or a captain with a passcode (on Swing's thread)
	private void sidebar()
	{
		if (selfButton == null)
		{
			return;
		}
		boolean on = config.selfPanel() || !config.captainPass().isBlank();
		if (on != selfShown)
		{
			if (on)
			{
				clientToolbar.addNavigation(selfButton);
			}
			else
			{
				clientToolbar.removeNavigation(selfButton);
			}
			selfShown = on;
		}
		selfPanel.render();
	}

	@Override
	protected void shutDown()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (selfButton != null)
			{
				clientToolbar.removeNavigation(selfButton);
			}
			selfButton = null;
			selfPanel = null;
			selfShown = false;
		});
		kills.flush();
		team.closePush();
		team.onWants(w -> { });
		gear.clear();
		eventBus.unregister(kills);
		eventBus.unregister(skilling);
		overlayManager.remove(boardOverlay);
		overlayManager.remove(boardButton);
		overlayManager.remove(tilePanel);
		mouseManager.unregisterMouseListener(boardOverlay);
		mouseManager.unregisterMouseWheelListener(boardOverlay);
		mouseManager.unregisterMouseListener(boardButton.mouse);
		keyManager.unregisterKeyListener(boardOverlay);
		boardOverlay.show(null, null, 0, null);
		team.clear();
		skilling.goals(null);
		skilling.reset(); // (turned on again while logged in: nothing gained meanwhile counts)
		kills.reset();
		popups.stop();
	}

	// A server answer (null: no team): the board window, the Skilling goals, the welcome and finished tiles
	private void apply(Wants w)
	{
		kills.goals(w);
		showBoard(w);
		skilling.goals(w);
		if (w != null)
		{
			popups.welcome(w);
			popups.finished(w.finished);
		}
	}

	// The board window and its button: while logged in, from the bingo's start until a day after its end
	private void showBoard(Wants w)
	{
		long now = System.currentTimeMillis();
		boolean on = w != null && client.getGameState() == GameState.LOGGED_IN && now >= w.start && now <= w.end + 24 * Team.HOUR;
		boardOverlay.show(on ? w.board : null, w == null ? null : w.name, w == null ? 0 : w.end, w == null ? null : w.finished);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!CabbingoConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		if ("url".equals(e.getKey()))
		{
			// another team: its finished tiles are not news
			popups.forget();
			team.closePush();
			team.fetch();
		}
		else if ("selfPanel".equals(e.getKey()) || "captainPass".equals(e.getKey()))
		{
			SwingUtilities.invokeLater(this::sidebar);
		}
		else if (e.getKey().startsWith("buttonIcon"))
		{
			executor.execute(this::loadIcon);
		}
		else if (FOLLOW_KEYS.contains(e.getKey()))
		{
			// both displays off: nothing followed; a source off: the tile it gave goes; else the infobox shown or removed
			boolean sourceOff = ("false".equals(e.getNewValue()) || "OFF".equals(e.getNewValue())) && e.getKey().startsWith("follow");
			if (!config.tilePanel() && !config.tileInfoBox())
			{
				boardOverlay.follow(null);
			}
			else if (sourceOff)
			{
				boardOverlay.unfollow("followPicked".equals(e.getKey()));
			}
			else
			{
				boardOverlay.syncBox();
			}
		}
		else if ("boardTile".equals(e.getKey()))
		{
			boardOverlay.tileSize(config.boardTile());
		}
		else if (SOUND_KEYS.contains(e.getKey()))
		{
			// a try of the picked sound
			boolean flip = "flipSound".equals(e.getKey()) || "testFlip".equals(e.getKey());
			clientThread.invoke(() -> popups.playSound(flip ? config.flipSound() : config.sound()));
		}
	}

	// The board window's and button's menus. Over the window: Hide details / Show details. The game's own entries stay
	// as they are (Jagex's rules forbid removing attack or player options; the window takes its clicks itself,
	// BoardOverlay, 2026-11-12). Over the button: Open / Close Bingo board, with or without shift (RuneLite shows an
	// overlay's own entries only with shift), unless an interface covers it.
	@Subscribe
	public void onPostMenuSort(PostMenuSort e)
	{
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || client.isMenuOpen())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (boardOverlay.covers(mouse.getX(), mouse.getY()))
		{
			menuEntry(boardOverlay.details() ? "Hide details" : "Show details", boardOverlay::toggleDetails);
			// a tile under the mouse: pin it, so the tile text panel and infobox follow it alone (user, 2026-11-24)
			String id = boardOverlay.tileIdAt(mouse.getX(), mouse.getY());
			if (id != null && (config.tilePanel() || config.tileInfoBox()))
			{
				boolean on = id.equals(boardOverlay.pinned());
				menuEntry(on ? "Unpin tile" : "Pin tile", () -> boardOverlay.pin(on ? null : id));
			}
			return;
		}
		// split private chat lines are no window: their Reply / Add ignore entries leave the button its menu
		boardButton.covered = Arrays.stream(entries).anyMatch(m -> m.getWidget() != null
			&& WidgetUtil.componentToInterface(m.getWidget().getId()) != InterfaceID.PM_CHAT);
		if (boardButton.hovered(mouse.getX(), mouse.getY()))
		{
			menuEntry(boardOverlay.isOpen() ? "Close" : "Open", boardOverlay::toggle);
		}
	}

	// one of ours, just below the game's left-click option (under Cancel when that is all), never the left click itself
	private void menuEntry(String option, Runnable action)
	{
		client.getMenu().createMenuEntry(-2) // -1 would be the top entry: the left click
			.setOption(option)
			.setTarget(ColorUtil.wrapWithColorTag("Bingo board", JagexColors.MENU_TARGET))
			.setType(MenuAction.RUNELITE)
			.setDeprioritized(true)
			.onClick(m -> action.run());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			team.fetch();
		}
		else if (e.getGameState() == GameState.LOGGING_IN)
		{
			team.offTeamTold = false; // (not at LOGGED_IN: that comes after every loading screen too)
			team.nameSent = false;
		}
		else if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			team.closePush();
			if (e.getGameState() == GameState.LOGIN_SCREEN)
			{
				boardOverlay.show(null, null, 0, null);
			}
			kills.logout();
			skilling.send();
			skilling.reset();
			updateTemple();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		popups.tick();
		if (team.inBingo())
		{
			team.openPush();
		}
		team.sendName();
		kills.tick();
		String player = team.playing();
		gear.watch(player);
		if (player != null)
		{
			skilling.tick(player);
		}
		if (templeName == null && client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
		{
			boolean normal = client.getWorldType().stream().noneMatch(OFF_HISCORES::contains);
			templeName = normal ? Team.name(client.getLocalPlayer().getName()) : null;
			templeXp = client.getOverallExperience();
		}
		kills.petTick();
	}

	// Skilling counts every five minutes (Skilling.send); RuneLite only schedules the plugin's own methods
	@Schedule(period = 5, unit = ChronoUnit.MINUTES, asynchronous = true)
	public void sendSkills()
	{
		skilling.send();
	}

	// The poll for the team's copy (Team.poll)
	@Schedule(period = 1, unit = ChronoUnit.MINUTES, asynchronous = true)
	public void refreshWants()
	{
		team.poll();
	}

	// TempleOSRS: the bingo's XP and kill count tiles count from its copy of the hiscores, which it only refreshes when
	// asked. Asked here on logout (and world hop) during the bingo, as RuneLite's own XP Updater does, unless that one
	// already asks TempleOSRS. Not from a world whose XP is not on the normal hiscores.
	private void updateTemple()
	{
		String name = templeName;
		long gained = client.getOverallExperience() - templeXp;
		templeName = null;
		if (name == null || templeXp < 0 || !team.inBingo())
		{
			return;
		}
		// the server checks the skilling counts up to here against TempleOSRS once it has this update (cheat mark)
		sender.send(Sender.payload("LOGOUT", name, "", new JsonObject()), false);
		if (gained <= 0 || !config.templeUpdate())
		{
			return;
		}
		// (XP Updater's TempleOSRS box is off by default, and it sends only past 10,000 XP gained)
		if ("true".equals(configManager.getConfiguration("runelite", "xpupdaterplugin"))
			&& "true".equals(configManager.getConfiguration("xpupdater", "templeosrs")) && gained > 10_000)
		{
			return;
		}
		HttpUrl url = new HttpUrl.Builder().scheme("https").host("templeosrs.com").addPathSegment("php")
			.addPathSegment("add_datapoint.php").addQueryParameter("player", name).build();
		http.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cabbingo: TempleOSRS update failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				response.close();
			}
		});
	}

	@Provides
	CabbingoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CabbingoConfig.class);
	}
}

package com.cabbingo;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

/**
 * What the player wears and carries, for the gear and inventory rules of kill count tiles and random events, and the
 * random event infobox while a rule is broken.
 */
@Singleton
class Gear
{
	// The game's equipment slots by the names the rules use (KillRules.SLOTS)
	private static final Map<String, EquipmentInventorySlot> SLOT_OF = new LinkedHashMap<>();
	static
	{
		SLOT_OF.put("head", EquipmentInventorySlot.HEAD);
		SLOT_OF.put("cape", EquipmentInventorySlot.CAPE);
		SLOT_OF.put("neck", EquipmentInventorySlot.AMULET);
		SLOT_OF.put("ammo", EquipmentInventorySlot.AMMO);
		SLOT_OF.put("weapon", EquipmentInventorySlot.WEAPON);
		SLOT_OF.put("body", EquipmentInventorySlot.BODY);
		SLOT_OF.put("shield", EquipmentInventorySlot.SHIELD);
		SLOT_OF.put("legs", EquipmentInventorySlot.LEGS);
		SLOT_OF.put("hands", EquipmentInventorySlot.GLOVES);
		SLOT_OF.put("feet", EquipmentInventorySlot.BOOTS);
		SLOT_OF.put("ring", EquipmentInventorySlot.RING);
	}
	// an event's icon that is an item picture: the infobox shows that item
	private static final Pattern ITEM_ICON = Pattern.compile("item-images/(\\d+)\\.png$");
	private static final int MYSTERY_BOX = ItemID.MACRO_QUIZ_MYSTERY_BOX;

	private final Client client;
	private final ItemManager itemManager;
	private final InfoBoxManager infoBoxManager;
	private final CabbingoPlugin plugin;
	private final KillRules killRules;
	private final Team team;

	// The random event infobox: shown while the player breaks a rule of a running random event (user, 2026-11-07),
	// so they know before they start.
	private RuleBox ruleBox;
	// the rules of running random events broken right now (watch): skilling and a pet then count for no tile
	private volatile List<String> ruleLines = Collections.emptyList();

	@Inject
	Gear(Client client, ItemManager itemManager, InfoBoxManager infoBoxManager, CabbingoPlugin plugin, KillRules killRules, Team team)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.infoBoxManager = infoBoxManager;
		this.plugin = plugin;
		this.killRules = killRules;
		this.team = team;
	}

	/** The broken rules of running random events, as of the last tick; empty while none is broken. */
	List<String> ruleLines()
	{
		return ruleLines;
	}

	static List<KillRules.Event> events(Wants w)
	{
		return w == null || w.events == null ? Collections.emptyList() : w.events;
	}

	/** What the player wears now: slot -> item name, empty slots left out. */
	Map<String, String> worn()
	{
		Map<String, String> out = new HashMap<>();
		ItemContainer c = client.getItemContainer(InventoryID.WORN);
		if (c == null)
		{
			return out;
		}
		SLOT_OF.forEach((slot, s) ->
		{
			Item item = c.getItem(s.getSlotIdx());
			if (item != null && item.getId() > 0)
			{
				out.put(slot, itemManager.getItemComposition(item.getId()).getName());
			}
		});
		int quiver = quiverAmmo(out.get("cape"));
		if (quiver > 0)
		{
			out.put("quiver", itemManager.getItemComposition(quiver).getName());
		}
		return out;
	}

	// The ammo in Dizana's quiver's own slot, only while a quiver (or the max cape with one) is worn; 0 for none
	private int quiverAmmo(String cape)
	{
		int id = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		return cape != null && cape.toLowerCase(Locale.ROOT).contains("dizana") && id > 0 ? id : 0;
	}

	// For the gear rules, every game tick: what the worn gear is worth by RuneLite's prices (ammo by its whole stack,
	// untradeables 0) and which worn items have no combat stats.
	private void lookAtGear(Map<String, String> worn)
	{
		List<int[]> items = new ArrayList<>(); // item id, quantity
		ItemContainer c = client.getItemContainer(InventoryID.WORN);
		for (Item item : c == null ? new Item[0] : c.getItems())
		{
			if (item.getId() > 0)
			{
				items.add(new int[]{item.getId(), item.getQuantity()});
			}
		}
		int quiver = quiverAmmo(worn.get("cape"));
		if (quiver > 0)
		{
			items.add(new int[]{quiver, client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT)});
		}
		long gp = 0;
		for (int[] i : items)
		{
			gp += itemManager.getItemPrice(i[0]) * i[1];
			ItemStats stats = itemManager.getItemStats(i[0]);
			ItemEquipmentStats e = stats == null ? null : stats.getEquipment();
			if (e == null || (e.getAstab() == 0 && e.getAslash() == 0 && e.getAcrush() == 0 && e.getAmagic() == 0 && e.getArange() == 0
				&& e.getDstab() == 0 && e.getDslash() == 0 && e.getDcrush() == 0 && e.getDmagic() == 0 && e.getDrange() == 0
				&& e.getStr() == 0 && e.getRstr() == 0 && e.getMdmg() == 0 && e.getPrayer() == 0))
			{
				killRules.statless.add(KillRules.key(itemManager.getItemComposition(i[0]).getName()));
			}
		}
		killRules.worth(gp);
	}

	/** The backpack's item names. */
	List<String> bag()
	{
		List<String> out = new ArrayList<>();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		for (Item item : inv == null ? new Item[0] : inv.getItems())
		{
			if (item.getId() > 0)
			{
				out.add(itemManager.getItemComposition(item.getId()).getName());
			}
		}
		return out;
	}

	// Every game tick: gear and inventory are noted for the kill count rules, and the infobox shows the broken rules of
	// running random events.
	void watch(String player)
	{
		Wants w = team.wants();
		boolean kcRules = w != null && w.kc.stream().anyMatch(g -> g.gear != null || g.carry != null || g.maxValue != null);
		boolean events = w != null && w.events != null && !w.events.isEmpty();
		if (player == null || (!kcRules && !events))
		{
			clear();
			return;
		}
		Map<String, String> worn = worn();
		List<String> bag = bag();
		lookAtGear(worn);
		// a random event's rules hold for every kill too
		killRules.saw(worn, bag);
		Map<String, Set<String>> now = new HashMap<>();
		worn.forEach((slot, name) -> now.put(slot, Collections.singleton(name)));
		long time = System.currentTimeMillis();
		List<String> lines = new ArrayList<>();
		KillRules.Event first = null;
		for (KillRules.Event ev : events ? w.events : Collections.<KillRules.Event>emptyList())
		{
			if (time < ev.from || time >= ev.to)
			{
				continue;
			}
			for (String line : KillRules.broken(ev, now, bag, bag, killRules.statless, killRules.worthNow()))
			{
				lines.add(KillRules.eventLine(line));
				first = first == null ? ev : first;
			}
		}
		ruleLines = lines;
		setRuleBox(first, lines);
	}

	void clear()
	{
		ruleLines = Collections.emptyList();
		setRuleBox(null, ruleLines);
	}

	private void setRuleBox(KillRules.Event ev, List<String> lines)
	{
		if (lines.isEmpty())
		{
			if (ruleBox != null)
			{
				infoBoxManager.removeInfoBox(ruleBox);
				ruleBox = null;
			}
			return;
		}
		String tip = String.join("</br>", lines);
		if (ruleBox != null && ruleBox.event == ev)
		{
			ruleBox.tip = tip;
			return;
		}
		if (ruleBox != null)
		{
			infoBoxManager.removeInfoBox(ruleBox);
		}
		Matcher m = ITEM_ICON.matcher(ev.icon == null ? "" : ev.icon);
		ruleBox = new RuleBox(itemManager.getImage(m.find() ? Integer.parseInt(m.group(1)) : MYSTERY_BOX), plugin, ev, tip);
		infoBoxManager.addInfoBox(ruleBox);
	}
}

package com.cabbingo;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

// A player's kills of one source, sent as one post (extra.kills) instead of one post per kill (2026-11-02): the loot
// worker writes its tally once per batch, which keeps it on the Workers Free plan. A kill a tile or the team's channel
// cares about never joins one; the plugin sends that kill alone, with its screenshot.
class KillBatch
{
	// Short on purpose: a RuneLite crash loses at most this much. Two minutes (was one) halves the posts and the loot
	// database writes of slow kills, a boss a minute or two each (2026-11-12)
	static final long WAIT = 120_000;
	// The server counts at most this many kills in one post
	static final int MAX = 100;

	static class Item
	{
		final int id;
		final String name;
		final long price; // each
		final int quantity;

		Item(int id, String name, long price, int quantity)
		{
			this.id = id;
			this.name = name;
			this.price = price;
			this.quantity = quantity;
		}
	}

	static class Batch
	{
		final String rsn;
		final String source;
		final String category;
		final long first;
		int kills;
		// by item id, the stacks of all kills added up
		final Map<Integer, Item> items = new LinkedHashMap<>();

		Batch(String rsn, String source, String category, long first)
		{
			this.rsn = rsn;
			this.source = source;
			this.category = category;
			this.first = first;
		}
	}

	private Batch open;

	// The kill joins the open batch of its player, source and category. Returns the batch it closed (another source,
	// or a full one) to send now, else null.
	synchronized Batch add(String rsn, String source, String category, List<Item> items, long now)
	{
		Batch closed = null;
		if (open != null && (open.kills >= MAX || !open.rsn.equals(rsn) || !open.source.equals(source) || !open.category.equals(category)))
		{
			closed = open;
			open = null;
		}
		if (open == null)
		{
			open = new Batch(rsn, source, category, now);
		}
		open.kills++;
		for (Item i : items)
		{
			open.items.merge(i.id, i, (a, b) -> new Item(a.id, a.name, a.price, a.quantity + b.quantity));
		}
		return closed;
	}

	// WAIT since the open batch's first kill
	synchronized boolean due(long now)
	{
		return open != null && now - open.first >= WAIT;
	}

	// The open batch, to send now; null when there is none
	synchronized Batch take()
	{
		Batch b = open;
		open = null;
		return b;
	}
}

package com.cabbingo;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Singleton;

// Kill count tiles (2026-11-06): kills of one monster that count only within the tile's food rule. On each kill of a
// goal's monster the plugin checks the backpack and what was eaten since the last kill; a kill that broke the rule is
// told in the chat and never sent. The kills that kept to it go out together, two minutes after the first, or at once when
// they finish the tile.
@Singleton
class KillRules
{
	static final long WAIT = 120_000; // each post that counts syncs the whole team: not more often (2026-11-12)

	/**
	 * Gear and inventory rules (GearRules in models/bingo.ts), of a kill count side or a random event. gear: slot (head,
	 * quiver, cape, neck, ammo, weapon, body, shield, legs, hands, feet, ring) -> empty, nostats, only or not; carry: one,
	 * all or not; maxValue: what everything worn may be worth at most, in gp.
	 */
	static class Rules
	{
		Map<String, Items> gear;
		Items carry;
		Long maxValue;
	}

	static class Items
	{
		String mode;
		List<String> items = new ArrayList<>();
	}

	/** A random event of the team with rules, from..to. */
	static class Event extends Rules
	{
		String title;
		String icon; // the event's picture, item-images/<id>.png for an item
		long from;
		long to;
	}

	// the slot's word in a warning, as gearLines words it
	private static final Map<String, String[]> SLOTS = new LinkedHashMap<>();
	static
	{
		String[][] slots = {{"head", "Head", "hat"}, {"quiver", "Quiver", "quiver ammo"}, {"cape", "Cape", "cape"}, {"neck", "Neck", "amulet"}, {"ammo", "Ammo", "ammo"},
			{"weapon", "Weapon", "weapon"}, {"body", "Body", "body armour"}, {"shield", "Shield", "shield"}, {"legs", "Legs", "leg armour"},
			{"hands", "Hands", "gloves"}, {"feet", "Feet", "boots"}, {"ring", "Ring", "ring"}};
		for (String[] s : slots)
		{
			SLOTS.put(s[0], new String[]{s[1], s[2]});
		}
	}

	private static String list(List<String> items, String word)
	{
		return items.size() < 2 ? String.join("", items)
			: String.join(", ", items.subList(0, items.size() - 1)) + " " + word + " " + items.get(items.size() - 1);
	}

	/**
	 * The rules broken, one line each in gearLines' words. worn: per slot every item it held (during a kill: since the
	 * last one; empty for nothing); bag: the inventory now; bagSeen: everything it held (the same as bag outside a kill);
	 * statless: the names (key) of items without combat stats; worth: the most the gear was worth, in gp.
	 */
	static List<String> broken(Rules r, Map<String, Set<String>> worn, Collection<String> bag, Collection<String> bagSeen, Set<String> statless, long worth)
	{
		List<String> out = new ArrayList<>();
		if (r == null)
		{
			return out;
		}
		for (Map.Entry<String, String[]> slot : SLOTS.entrySet())
		{
			Items s = r.gear == null ? null : r.gear.get(slot.getKey());
			if (s == null)
			{
				continue;
			}
			Set<String> had = worn.getOrDefault(slot.getKey(), Collections.emptySet());
			Set<String> listed = keys(s.items);
			if ("empty".equals(s.mode) && !had.isEmpty())
			{
				out.add("No " + slot.getValue()[1] + " allowed");
			}
			if ("nostats".equals(s.mode) && (had.isEmpty() || had.stream().anyMatch(n -> !statless.contains(key(n)))))
			{
				out.add(slot.getValue()[0] + ": an item without stats");
			}
			if ("only".equals(s.mode) && (had.isEmpty() || had.stream().anyMatch(n -> !listed.contains(key(n)))))
			{
				out.add(slot.getValue()[0] + ": only " + list(s.items, "or"));
			}
			if ("not".equals(s.mode) && had.stream().anyMatch(n -> listed.contains(key(n))))
			{
				out.add("No " + list(s.items, "or") + " allowed");
			}
		}
		Items c = r.carry;
		if (c != null)
		{
			Set<String> listed = keys(c.items);
			Set<String> now = keys(bag);
			if ("one".equals(c.mode) && listed.stream().noneMatch(now::contains))
			{
				out.add("Carry " + list(c.items, "or"));
			}
			if ("all".equals(c.mode) && !now.containsAll(listed))
			{
				out.add("Carry " + list(c.items, "and"));
			}
			if ("not".equals(c.mode) && keys(bagSeen).stream().anyMatch(listed::contains))
			{
				out.add("No " + list(c.items, "or") + " in the inventory");
			}
		}
		if (r.maxValue != null && worth > r.maxValue)
		{
			out.add(String.format(Locale.US, "Gear worth at most %,d gp", r.maxValue));
		}
		return out;
	}

	/** A broken rule of a random event, as the infobox and the chat say it: "Random event: no hat allowed". */
	static String eventLine(String line)
	{
		return "Random event: " + Character.toLowerCase(line.charAt(0)) + line.substring(1);
	}

	private static Set<String> keys(Collection<String> names)
	{
		return names.stream().map(KillRules::key).collect(Collectors.toSet());
	}

	// what was worn and carried since the last kill, for the gear rules (saw, on every game tick)
	private final Map<String, Set<String>> wornSeen = new HashMap<>();
	private final Set<String> bagSeen = new HashSet<>();
	// the items seen worn that have no combat stats (key), as the plugin found them in the game's item stats
	final Set<String> statless = ConcurrentHashMap.newKeySet();
	private long worthNow; // what the gear is worth now, in gp
	private long worthSeen; // the most it was worth since the last kill

	/** What the gear worn is worth now (each game tick). */
	synchronized void worth(long gp)
	{
		worthNow = gp;
		worthSeen = Math.max(worthSeen, gp);
	}

	synchronized long worthNow()
	{
		return worthNow;
	}

	/** What the player wears (slot -> item) and carries now; kept until the next kill. */
	synchronized void saw(Map<String, String> worn, Collection<String> bag)
	{
		worn.forEach((slot, name) -> wornSeen.computeIfAbsent(slot, k -> new HashSet<>()).add(name));
		bagSeen.addAll(bag);
	}

	/** A kill count side the team can still add to (the server's kcGoals). */
	static class Goal extends Rules
	{
		String id; // the tile's id, ':flip' for its flipped side
		String title;
		String source; // the monster, as the loot tracker names it
		int left; // kills still needed
		Food food; // null: any food
		Food potions; // null: any potion
		long from; // a tile of the day: its day, from..to; 0 for a grid tile
		long to;
		int[] marks; // the kills still to go at which a screenshot goes along: the tile's proof (kcMarks)
	}

	static class Food
	{
		String mode; // only, not, none
		List<String> items = new ArrayList<>();
	}

	/** One item of the backpack, or one that was eaten: its name and whether it can be eaten or drunk. */
	static class Carried
	{
		final String name;
		final boolean food;
		final boolean potion;

		Carried(String name, boolean food, boolean potion)
		{
			this.name = name;
			this.food = food;
			this.potion = potion;
		}
	}

	private final List<String> eaten = new ArrayList<>(); // since the last kill
	private final List<String> drunk = new ArrayList<>(); // since the last kill
	private final Map<String, Integer> pending = new LinkedHashMap<>(); // goal id -> kills not sent yet
	private long due; // 0: nothing waiting
	private boolean now; // a goal is finished by what waits, or a mark was hit: send at the next chance
	private boolean shot; // a mark was hit: the send takes a screenshot along

	/** What the player ate (the "Eat" option), until the next kill. */
	synchronized void ate(String name)
	{
		eaten.add(name);
	}

	/** What the player drank (the "Drink" option), until the next kill. */
	synchronized void drank(String name)
	{
		drunk.add(name);
	}

	synchronized void forgetEaten()
	{
		eaten.clear();
		drunk.clear();
	}

	/** Why a kill breaks the food rule, or null when it keeps to it. */
	static String broken(Food food, Collection<Carried> backpack, Collection<String> ate)
	{
		return broken(food, backpack, ate, false);
	}

	/**
	 * The same for food or, with potion, for potions: anything with "Drink", by name without the dose ("Prayer
	 * potion(4)" is "Prayer potion(1)" too).
	 */
	static String broken(Food rule, Collection<Carried> backpack, Collection<String> used, boolean potion)
	{
		if (rule == null)
		{
			return null;
		}
		Set<String> listed = new HashSet<>();
		for (String i : rule.items)
		{
			listed.add(potion ? dose(i) : key(i));
		}
		List<Carried> all = new ArrayList<>(backpack);
		for (String a : used)
		{
			all.add(new Carried(a, !potion, potion));
		}
		for (Carried c : all)
		{
			boolean kind = potion ? c.potion : c.food;
			String k = potion ? dose(c.name) : key(c.name);
			boolean bad = "not".equals(rule.mode) ? listed.contains(k)
				: "only".equals(rule.mode) ? kind && !listed.contains(k)
				: kind; // none
			if (bad)
			{
				return c.name;
			}
		}
		return null;
	}

	private static String dose(String name)
	{
		return key(name).replaceFirst("\\(\\d\\)$", "");
	}

	/**
	 * A kill of source: each goal of that monster takes it when it keeps to that goal's food, potion and gear rules (worn:
	 * slot -> item now). A kill that broke the rules of a random event running at the kill counts for no tile either
	 * (user, 2026-11-07). Returns the goals whose rule it broke, with what broke it, for the chat warning.
	 */
	synchronized Map<Goal, String> kill(List<Goal> goals, String source, Collection<Carried> backpack, Map<String, String> worn, List<Event> events, long time)
	{
		return kill(goals, source, null, backpack, worn, events, time);
	}

	/**
	 * The same, where the kill is also one of mode: a raid's harder mode ("Theatre of Blood Hard Mode"), whose chest the
	 * Loot Tracker names as the normal raid. A goal of either takes it; mode is matched on its letters only, so
	 * "Theatre of Blood: Hard Mode" fits too.
	 */
	synchronized Map<Goal, String> kill(List<Goal> goals, String source, String mode, Collection<Carried> backpack, Map<String, String> worn, List<Event> events, long time)
	{
		List<String> eventLines = eventsBroken(events, worn, names(backpack), time);
		Map<Goal, String> broke = new LinkedHashMap<>();
		for (Goal g : goals)
		{
			if (g.left <= 0 || g.source == null || !(g.source.trim().equalsIgnoreCase(source.trim()) || mode != null && letters(g.source).equals(letters(mode)))
				|| time < g.from || (g.to > 0 && time >= g.to))
			{
				continue;
			}
			String why = broken(g.food, backpack, eaten);
			why = why != null ? why : broken(g.potions, backpack, drunk, true);
			if (why == null)
			{
				List<String> gear = broken(g, wornSeen, names(backpack), bagSeen, statless, worthSeen);
				gear.addAll(eventLines);
				why = gear.isEmpty() ? null : String.join(", ", gear);
			}
			if (why != null)
			{
				broke.put(g, why);
				continue;
			}
			pending.merge(g.id, 1, Integer::sum);
			g.left--;
			for (int mark : g.marks == null ? new int[0] : g.marks)
			{
				shot |= mark == g.left;
			}
			now |= g.left <= 0 || shot;
			if (due == 0)
			{
				due = time + WAIT;
			}
		}
		eaten.clear();
		drunk.clear();
		next(worn, names(backpack));
		return broke;
	}

	/**
	 * The rules of the random events running at time that the kill broke, with what is worn and carried now: one line
	 * each, as eventLine says it. They hold for every tile, drops and kill counts alike (user, 2026-11-07).
	 */
	synchronized List<String> eventsBroken(List<Event> events, Map<String, String> worn, Collection<String> bag, long time)
	{
		saw(worn, bag);
		List<String> out = new ArrayList<>();
		for (Event e : events)
		{
			if (time >= e.from && time < e.to)
			{
				broken(e, wornSeen, bag, bagSeen, statless, worthSeen).forEach(l -> out.add(eventLine(l)));
			}
		}
		return out;
	}

	/** After a kill: the next one starts from what is worn and carried now. */
	synchronized void next(Map<String, String> worn, Collection<String> bag)
	{
		wornSeen.clear();
		bagSeen.clear();
		worthSeen = worthNow;
		saw(worn, bag);
	}

	private static List<String> names(Collection<Carried> backpack)
	{
		return backpack.stream().map(c -> c.name).collect(Collectors.toList());
	}

	synchronized boolean due(long time)
	{
		return now || (due != 0 && time >= due);
	}

	/** The kills of a goal not sent yet: a refetched goal's left does not have them (Kills.goals). */
	synchronized int pending(String id)
	{
		return pending.getOrDefault(id, 0);
	}

	/** The kills waiting, per goal id; empties them. */
	synchronized Map<String, Integer> take()
	{
		Map<String, Integer> out = new LinkedHashMap<>(pending);
		pending.clear();
		due = 0;
		now = false;
		shot = false;
		return out;
	}

	/** Whether the next send takes a screenshot along; ask before take(). */
	synchronized boolean shot()
	{
		return shot;
	}

	static String letters(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}
}

package com.cabbingo;

import com.google.gson.Gson;
