/**
 * Every kill, PvP kill and pet of a bingo player: kills of one source go out together (KillBatch), a kill a tile or
 * the team's channel cares about alone with its screenshot, and kill count tiles' kills within their rules
 * (KillRules). On the EventBus while the plugin runs.
 */
@Slf4j
@Singleton
class Kills
{
	private static final String[] PET_MESSAGES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};
	private static final String COLLECTION_LOG = "New item added to your collection log: ";
	// A raid's harder modes, each with the raid the Loot Tracker names its chest after (it has no modes)
	private static final String[][] RAID_MODES = {
		{"Chambers of Xeric Challenge Mode", "Chambers of Xeric"},
		{"Theatre of Blood Hard Mode", "Theatre of Blood"},
		{"Tombs of Amascut Expert Mode", "Tombs of Amascut"},
	};
	// The game's kill count line, as RuneLite's chat commands read it: "Your Royal Titans kill count is: 375.", "Your
	// completed Theatre of Blood: Hard Mode count is: 5.", "Your subdued Wintertodt count is: 9.", "Your Gauntlet
	// completion count is: 3.", "Your Barrows chest count is: 40."
	private static final Pattern KC_LINE = Pattern.compile("^Your (?:completion count for |subdued |completed )?(.+?) (?:(?:kill|harvest|lap|completion) )?(?:count )?is: ?[0-9,]+");
	// Guardians of the Rift says it apart: "Amount of rifts you have closed: 12."
	private static final Pattern RIFTS = Pattern.compile("^Amount of rifts you have closed: ?[0-9,]+");
	// "Your completed Theatre of Blood: Hard Mode count is: 5." (RuneLite's chat commands read the same line)
	private static final Pattern RAID_DONE = Pattern.compile("^Your completed (.+?) count is");
	// Pyramid Plunder's sceptre comes from a golden chest or sarcophagus straight into the backpack, with no loot event
	// (RuneLite's Loot Tracker misses it too), and the game throws the player out of the pyramid at once (user,
	// 2026-11-27: one did not count). It lands in the backpack outside, or on the floor there when the backpack is full:
	// either counts within PLUNDER_TICKS of leaving, the floor one at once, so a late pick-up is no loss (user).
	// Backpack and worn count as one (taking a worn one off is no find), and only above the most held since entering,
	// so a sceptre dropped and picked up again is no find either. A found one has charges: the uncharged one never counts,
	// but it is held all the same, so charging it at the mummy inside is no find.
	private static final int PYRAMID_PLUNDER = 7749;
	private static final int PLUNDER_TICKS = 10;
	private static final Set<Integer> SCEPTRES = Set.of(ItemID.PHARAOHS_SCEPTRE_CHARGED, ItemID.PHARAOHS_SCEPTRE_CHARGED_INITIAL);
	private static final Set<Integer> HELD_SCEPTRES = Set.of(ItemID.PHARAOHS_SCEPTRE, ItemID.PHARAOHS_SCEPTRE_CHARGED, ItemID.PHARAOHS_SCEPTRE_CHARGED_INITIAL);

	private final Client client;
	private final ItemManager itemManager;
	private final Gson gson;
	private final Team team;
	private final Gear gear;
	private final Sender sender;
	private final KillRules killRules;
	private final BoardOverlay boardOverlay;

	// Kills of one source go out together, two minutes after the first (KillBatch)
	private final KillBatch kills = new KillBatch();
	// who made the kills that kept to a kill count tile's rules (KillRules)
	private volatile String kcRsn;
	// the mode of the raid the last completion message named (null: a normal raid), until that raid's chest comes in
	private volatile String[] raidMode;
	// A pet message waits a few ticks for the collection log line that names the pet.
	private int petTicks = -1;
	private String petName;
	private boolean petDuplicate;
	// ticks since the player was last inside Pyramid Plunder (-1: not lately); the most sceptres held (backpack and
	// worn) since entering it (-1: not looked at since login); the tick a sceptre was last dropped by hand
	private int plunderTicks = -1;
	private int sceptres = -1;
	private int sceptreId = ItemID.PHARAOHS_SCEPTRE_CHARGED_INITIAL;
	private int sceptreDropped = -10;

	@Inject
	Kills(Client client, ItemManager itemManager, Gson gson, Team team, Gear gear, Sender sender, KillRules killRules, BoardOverlay boardOverlay)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.gson = gson;
		this.team = team;
		this.gear = gear;
		this.sender = sender;
		this.killRules = killRules;
		this.boardOverlay = boardOverlay;
	}

	/** Sends what waits: the open batch and the kill count kills (logout, hop, shutDown). */
	void flush()
	{
		sendKills(kills.take());
		sendKc();
	}

	/**
	 * A fresh copy of the kill count goals: the server does not have the kills still waiting here (sent up to two minutes
	 * late), so they come off its count, or a refetch would put them back and delay the finish and its proof.
	 */
	void goals(Wants w)
	{
		if (w != null && w.kc != null)
		{
			w.kc.forEach(g -> g.left -= killRules.pending(g.id));
		}
	}

	/** Logout or hop: what waits goes out, and the next kill starts with nothing eaten. */
	void logout()
	{
		flush();
		killRules.forgetEaten();
		sceptres = -1;
	}

	void reset()
	{
		petTicks = -1;
	}

	/** Once a tick: the batch two minutes after its first kill, or once the bingo window has closed. */
	void tick()
	{
		boolean inPyramid = client.getLocalPlayer() != null && client.getLocalPlayer().getWorldLocation().getRegionID() == PYRAMID_PLUNDER;
		if (inPyramid && plunderTicks != 0)
		{
			sceptres = held();
		}
		plunderTicks = inPyramid ? 0 : plunderTicks < 0 || plunderTicks >= PLUNDER_TICKS ? -1 : plunderTicks + 1;
		// once a tick, not on each container change: a worn sceptre taken off changes worn and backpack one after the other
		int now = held();
		if (sceptres >= 0 && now > sceptres && plunderTicks >= 0)
		{
			loot("Pyramid Plunder", "EVENT", Collections.singletonList(new ItemStack(sceptreId, now - sceptres)));
		}
		// inside the window the most held only rises: dropped and picked up again is no find
		sceptres = plunderTicks >= 0 ? Math.max(sceptres, now) : now;
		if (kills.due(System.currentTimeMillis()) || !team.inBingo())
		{
			sendKills(kills.take());
		}
		if (killRules.due(System.currentTimeMillis()))
		{
			sendKc();
		}
	}

	// Every NPC kill and pickpocket, as the server reports it. RuneLite also sends most kills as NpcLootReceived (loot
	// seen on the ground); RuneLite's own Loot Tracker only takes this one, and so does this plugin, or a kill posts twice.
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot e)
	{
		loot(e.getComposition().getName(), "NPC", e.getItems());
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived e)
	{
		loot("a player", "PLAYER", e.getItems()); // never the other player's name: RuneLite's rules forbid sending it
	}

	// Raids, chests, clues and the rest the Loot Tracker sees. Its NPC, PLAYER and PICKPOCKET loot comes in above already.
	@Subscribe
	public void onLootReceived(LootReceived e)
	{
		if (e.getType() == LootRecordType.EVENT)
		{
			loot(e.getName(), e.getType().name(), e.getItems());
		}
	}

	// sceptres in the backpack and worn, charged or not
	private int held()
	{
		int n = 0;
		for (int inv : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer c = client.getItemContainer(inv);
			for (Item item : c == null ? new Item[0] : c.getItems())
			{
				if (HELD_SCEPTRES.contains(item.getId()))
				{
					n += item.getQuantity();
				}
				if (SCEPTRES.contains(item.getId()))
				{
					sceptreId = item.getId();
				}
			}
		}
		return n;
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned e)
	{
		TileItem item = e.getItem();
		// a sceptre dropped by hand lands a tick or two after the click: no find
		if (plunderTicks >= 0 && SCEPTRES.contains(item.getId()) && item.getOwnership() == TileItem.OWNERSHIP_SELF
			&& client.getTickCount() - sceptreDropped > 2)
		{
			sceptres = Math.max(sceptres, 0) + item.getQuantity(); // (its pick-up then counts no more)
			loot("Pyramid Plunder", "EVENT", Collections.singletonList(new ItemStack(item.getId(), item.getQuantity())));
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		// food eaten during a kill counts for a kill count tile's food rule, like food in the backpack
		if ("Eat".equals(e.getMenuOption()))
		{
			killRules.ate(Text.removeTags(e.getMenuTarget()));
		}
		// and potions drunk for its potion rule
		if ("Drink".equals(e.getMenuOption()))
		{
			killRules.drank(Text.removeTags(e.getMenuTarget()));
		}
		if ("Drop".equals(e.getMenuOption()) && SCEPTRES.contains(e.getItemId()))
		{
			sceptreDropped = client.getTickCount();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String text = e.getMessage();
		templeKill(Text.removeTags(text));
		Matcher done = RAID_DONE.matcher(Text.removeTags(text));
		if (done.find())
		{
			String raid = KillRules.letters(done.group(1));
			raidMode = Arrays.stream(RAID_MODES).filter(m -> KillRules.letters(m[0]).equals(raid)).findFirst().orElse(null);
			return;
		}
		for (String pet : PET_MESSAGES)
		{
			if (text.startsWith(pet))
			{
				petTicks = 3;
				petName = null;
				petDuplicate = text.contains("would have been");
				return;
			}
		}
		if (petTicks >= 0 && text.startsWith(COLLECTION_LOG))
		{
			petName = text.substring(COLLECTION_LOG.length()).replaceAll("<[^>]*>", "").trim();
		}
	}

	/** The boss, raid or minigame a kill count line names ("Royal Titans"); null for any other message. */
	static String kcName(String message)
	{
		Matcher m = KC_LINE.matcher(message);
		return m.find() ? m.group(1) : RIFTS.matcher(message).find() ? "Guardians of the Rift" : null;
	}

	// TempleOSRS kill tiles: the server counts them from TempleOSRS, later; the board shows the kill now (user,
	// 2026-11-20). Display only, nothing is sent. From the game's kill count line, one a kill (user, 2026-11-24): loot
	// misses kills without any (Jad, Zuk, a destroyed Araxxor) and counts a Guardians of the Rift game per search.
	// Not for a kill that broke a random event's rules, nor one a kill count goal already counts.
	private void templeKill(String message)
	{
		String name = kcName(message);
		Wants w = team.wants();
		if (name == null || w == null || team.playing() == null || !team.templeCounts() || !gear.ruleLines().isEmpty())
		{
			return;
		}
		for (String id : boardOverlay.templeKillTiles(name))
		{
			if (w.kc == null || w.kc.stream().noneMatch(g -> id.equals(g.id)))
			{
				boardOverlay.templeCounted(id, 1);
			}
		}
	}

	/** Once a tick: a pet goes out once its collection log line came, or a few ticks after its message. */
	void petTick()
	{
		if (petTicks < 0 || petTicks-- > 0 && petName == null)
		{
			return;
		}
		petTicks = -1;
		String rsn = team.playing();
		if (rsn == null)
		{
			return;
		}
		JsonObject extra = new JsonObject();
		if (petName != null)
		{
			extra.addProperty("petName", petName);
		}
		extra.addProperty("duplicate", petDuplicate);
		String content = "**" + rsn + "** got a pet" + (petName != null ? ": " + petName : "") + (petDuplicate ? " (duplicate)" : "");
		List<String> ruleLines = gear.ruleLines();
		if (!ruleLines.isEmpty())
		{
			extra.add("broke", gson.toJsonTree(ruleLines));
			content += "\nFor no tile: " + String.join(", ", ruleLines);
		}
		sender.send(Sender.payload("PET", rsn, content, extra), true);
	}

	private void loot(String source, String category, Collection<ItemStack> stacks)
	{
		String rsn = team.playing();
		if (rsn == null || source == null)
		{
			return;
		}
		Wants w = team.wants();
		if (w == null)
		{
			return; // (dropped since playing() looked)
		}
		// a running random event's rules hold for every tile (user, 2026-11-07): a kill that broke one still goes to the
		// gp lists and Discord, with the rules it broke (extra.broke), and the server counts it for no tile
		Map<String, String> worn = gear.worn();
		List<String> bag = gear.bag();
		List<String> broke = killRules.eventsBroken(Gear.events(w), worn, bag, System.currentTimeMillis());
		if (w.kc != null && !w.kc.isEmpty() && !category.equals("PLAYER"))
		{
			checkKill(rsn, source, w.kc);
		}
		else
		{
			killRules.next(worn, bag);
		}
		if (stacks.isEmpty())
		{
			return;
		}
		List<KillBatch.Item> items = new ArrayList<>();
		long value = 0;
		boolean wanted = false;
		boolean unique = false;
		for (ItemStack stack : stacks)
		{
			String name = itemManager.getItemComposition(stack.getId()).getName();
			long price = itemManager.getItemPrice(stack.getId());
			items.add(new KillBatch.Item(stack.getId(), name, price, stack.getQuantity()));
			value += price * stack.getQuantity();
			wanted |= w.items.contains(name.toLowerCase(Locale.ROOT).replaceFirst(" \\(uncharged\\)$", "")); // charged or not, as the server keys items
			unique |= w.uniques.contains(name.toLowerCase(Locale.ROOT));
		}
		// A screenshot where the server sends the post to the team's channel, or a tile counts its value.
		String sourceKey = category.equals("PLAYER") ? "pvp" : source.trim().toLowerCase(Locale.ROOT);
		Double min = w.sources == null ? null : w.sources.get(sourceKey);
		boolean shot = wanted || value >= w.big || (min != null && value >= min);
		if (!broke.isEmpty() && (wanted || (min != null && value >= min)))
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"<col=ff0000>The drop is invalidated for the tiles</col> (" + Text.escapeJagex(String.join(", ", broke)) + ")", null);
		}
		// Such a kill, a unique, PvP and one that broke a random event go alone (the whole drop, its own proof), after the
		// open batch; any other kill joins the batch of its source.
		if (shot || unique || category.equals("PLAYER") || !broke.isEmpty())
		{
			sendKills(kills.take());
			sendLoot(rsn, source, category, items, 1, shot, broke);
		}
		else
		{
			sendKills(kills.add(rsn, source, category, items, System.currentTimeMillis()));
		}
	}

	// A kill of a kill count tile's monster: the backpack now and what was eaten since the last kill, against each tile's
	// food rule. A kill that broke one is said in the chat and never sent for that tile (user, 2026-11-06).
	private void checkKill(String rsn, String source, List<KillRules.Goal> goals)
	{
		List<KillRules.Carried> backpack = new ArrayList<>();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		for (Item item : inv == null ? new Item[0] : inv.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}
			ItemComposition c = itemManager.getItemComposition(item.getId());
			List<String> actions = Arrays.asList(c.getInventoryActions());
			backpack.add(new KillRules.Carried(c.getName(), actions.contains("Eat"), actions.contains("Drink")));
		}
		kcRsn = rsn;
		Map<KillRules.Goal, Integer> left = new HashMap<>();
		goals.forEach(g -> left.put(g, g.left));
		// a harder mode's chest also counts for that mode's tiles (and still for the raid's own)
		String[] mode = raidMode;
		if (mode != null && mode[1].equalsIgnoreCase(source.trim()))
		{
			raidMode = null;
		}
		else
		{
			mode = null;
		}
		Map<KillRules.Goal, String> broke = killRules.kill(goals, source, mode == null ? null : mode[0], backpack, gear.worn(), Gear.events(team.wants()), System.currentTimeMillis());
		// the kills that counted show on the board window now; the server has them a minute later (KillBatch)
		goals.stream().filter(g -> g.left < left.get(g)).forEach(g -> boardOverlay.counted(g.id, 1));
		log.debug("Cabbingo: kill of {}, kill count tiles {}, broke {}", source, goals.stream().map(g -> g.source + "/" + g.left).collect(Collectors.toList()), broke.values());
		broke.forEach((g, why) ->
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"<col=ff0000>The kill is invalidated for the tile: " + Text.escapeJagex(g.title) + "</col> (" + Text.escapeJagex(why) + ")", null));
	}

	// The kills that kept to their tile's food rule, per tile side: the server adds them to the tiles
	private void sendKc()
	{
		boolean shot;
		Map<String, Integer> taken;
		synchronized (killRules)
		{
			shot = killRules.shot();
			taken = killRules.take();
		}
		String rsn = kcRsn;
		if (taken.isEmpty() || rsn == null)
		{
			return;
		}
		JsonObject counts = new JsonObject();
		taken.forEach(counts::addProperty);
		JsonObject extra = new JsonObject();
		extra.add("kills", counts);
		// the message with the screenshot: who, and per tile how many kills and how many are left
		StringBuilder lines = new StringBuilder("**" + rsn + "**");
		Wants w = team.wants();
		for (KillRules.Goal g : w == null ? Collections.<KillRules.Goal>emptyList() : w.kc)
		{
			if (taken.containsKey(g.id))
			{
				lines.append('\n').append(taken.get(g.id)).append(" x ").append(g.source).append(" for ").append(g.title)
					.append(" (").append(Math.max(0, g.left)).append(" to go)");
			}
		}
		// a screenshot at kcMarks: it goes to the team's channel, the tile's proof
		sender.send(Sender.payload("KC", rsn, lines.toString(), extra), shot);
	}

	private void sendKills(KillBatch.Batch b)
	{
		if (b != null)
		{
			sendLoot(b.rsn, b.source, b.category, new ArrayList<>(b.items.values()), b.kills, false, Collections.emptyList());
		}
	}

	// extra.kills: how many kills the items are from, their stacks added up (1 for a single kill)
	private void sendLoot(String rsn, String source, String category, List<KillBatch.Item> items, int n, boolean shot, List<String> broke)
	{
		JsonArray list = new JsonArray();
		StringBuilder lines = new StringBuilder();
		long value = 0;
		for (KillBatch.Item i : items)
		{
			JsonObject item = new JsonObject();
			item.addProperty("id", i.id);
			item.addProperty("name", i.name);
			item.addProperty("quantity", i.quantity);
			item.addProperty("priceEach", i.price);
			list.add(item);
			value += i.price * i.quantity;
			lines.append('\n').append(i.quantity).append(" x ").append(i.name);
		}
		JsonObject extra = new JsonObject();
		extra.addProperty("source", source);
		extra.addProperty("category", category);
		extra.addProperty("kills", n);
		extra.add("items", list);
		if (!broke.isEmpty())
		{
			extra.add("broke", gson.toJsonTree(broke));
			lines.append("\nFor no tile: ").append(String.join(", ", broke));
		}
		String content = "**" + rsn + "**: " + source + (n > 1 ? " x" + n : "") + " (" + String.format(Locale.ROOT, "%,d", value) + " gp)" + lines;
		// (Discord takes at most 2,000 characters)
		if (content.length() > 1900)
		{
			content = content.substring(0, 1900) + "\n...";
		}
		sender.send(Sender.payload("LOOT", rsn, content, extra), shot);
	}
}

package com.cabbingo;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * The game's own popup (the collection log's "New item") for each tile side, row, column or diagonal the team finished,
 * and the welcome at the first login of a bingo, one at a time, each with its sound and a chat message.
 */
@Slf4j
@Singleton
class Popups
{
	// The game's own popup (the collection log's "New item"): interface 660 over the game view, started by script 3343.
	private static final int POPUP = InterfaceID.NOTIFICATION_DISPLAY;
	private static final int POPUP_SCRIPT = 3343;
	private static final String SEEN = "seen";

	static class Popup
	{
		final String title;
		final String text;
		final String chat; // the chatbox message that goes with it; null for none
		final boolean flip; // a flipped side: the flipped tile sound
		final String id; // the finished side; null for the welcome

		Popup(String title, String text, String chat, boolean flip, String id)
		{
			this.title = title;
			this.text = text;
			this.chat = chat;
			this.flip = flip;
			this.id = id;
		}
	}

	private final Client client;
	private final ClientThread clientThread;
	private final CabbingoConfig config;
	private final ConfigManager configManager;
	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executor;

	// The finished tile sides already known (by id); null until the first answer, so a login shows no old ones.
	private Set<String> finishedSeen;
	// when each side last got its popup: a post's X-Finished must not bring back one the live line's fetch already
	// showed while the post was on its way (the same tile popped up twice, 2026-11-10)
	private final Map<String, Long> poppedAt = new HashMap<>();
	// Titles waiting for the game's popup, one at a time.
	private final Queue<Popup> popups = new ConcurrentLinkedQueue<>();
	private long soundUntil; // client thread only
	// our popup while it is open, and since when the next one waits (0: none waits)
	private WidgetNode popupNode;
	private long popupWaiting;

	@Inject
	Popups(Client client, ClientThread clientThread, CabbingoConfig config, ConfigManager configManager, AudioPlayer audioPlayer, ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.configManager = configManager;
		this.audioPlayer = audioPlayer;
		this.executor = executor;
	}

	/** The sides already popped up, kept over restarts: one finished while the player was away pops up at the next login. */
	synchronized void start()
	{
		String seen = configManager.getConfiguration(CabbingoConfig.GROUP, SEEN);
		finishedSeen = seen == null ? null : seen.isEmpty() ? new HashSet<>() : new HashSet<>(Arrays.asList(seen.split(",")));
	}

	/** Popups not shown yet come again at the next start. */
	void stop()
	{
		unsee(popups.stream().map(p -> p.id).filter(Objects::nonNull).toArray(String[]::new), Long.MAX_VALUE);
		synchronized (this)
		{
			finishedSeen = null;
		}
		popups.clear();
	}

	/** Another team (a new Team URL): its finished tiles are not news. */
	void forget()
	{
		synchronized (this)
		{
			finishedSeen = null;
		}
		configManager.unsetConfiguration(CabbingoConfig.GROUP, SEEN);
	}

	// The first login after a bingo starts: a welcome. Only when logged in, or the welcome could go to a login nobody sees.
	void welcome(Wants w)
	{
		long now = System.currentTimeMillis();
		String start = String.valueOf(w.start);
		if (client.getGameState() == GameState.LOGGED_IN && now >= w.start && now <= w.end && !start.equals(config.welcomed()))
		{
			String name = w.name == null || w.name.isEmpty() ? "Your bingo" : w.name;
			String mode = w.mode == null || w.mode.isEmpty() ? "Bingo" : w.mode;
			popups.add(new Popup(Text.escapeJagex(name), "<col=ffffff>" + Text.escapeJagex(mode) + "</col> has started.<br>Good luck and enjoy!", null, false, null));
			configManager.setConfiguration(CabbingoConfig.GROUP, "welcomed", start);
		}
	}

	// A tile side, row, column or diagonal (id row:i, col:i, diag:i) the team finished since the last answer gets the game's popup, as
	// League tasks do, and a chat message with the tile's description. While a captain still has to approve the drops
	// that finish it, the points read "on approval". Approved later, it shows no second popup.
	synchronized void finished(List<Finished> finished)
	{
		Set<String> ids = new HashSet<>();
		// the board's last tile: "Bingo completed!" with the team's total after the tile, no row/column/diagonal popups
		// (user, 2026-11-15)
		boolean full = finishedSeen != null && !finishedSeen.contains("bingo") && finished.stream().anyMatch(f -> f.id.equals("bingo"));
		if (full)
		{
			popups.removeIf(p -> p.id != null && isLine(p.id));
		}
		for (Finished f : finished)
		{
			ids.add(f.id);
			if (f.id.equals("bingo"))
			{
				if (full)
				{
					String total = f.points + (f.points == 1 ? " point" : " points");
					popups.add(new Popup("Bingo completed!", "Total points: <col=ffffff>" + f.points + "</col>",
						"<col=ef1020>Bingo completed!</col> Total points: " + total, false, f.id));
					poppedAt.put(f.id, System.currentTimeMillis());
				}
				continue;
			}
			if (finishedSeen != null && !finishedSeen.contains(f.id) && !(full && isLine(f.id)))
			{
				String kind = f.id.startsWith("row:") ? "Row" : f.id.startsWith("col:") ? "Column" : f.id.startsWith("diag:") ? "Diagonal" : "Tile";
				String name = Text.escapeJagex(f.title);
				String text = kind + " completed: <col=ffffff>" + name + "</col><br>"
					+ (f.wait ? "Points on approval: " : "Points earned: ") + "<col=ffffff>" + f.points + "</col>";
				String chat = "<col=ef1020>" + name + "</col> completed (" + f.points + (f.points == 1 ? " point" : " points")
					+ (f.wait ? " once approved" : "") + ")"
					+ (f.description == null || f.description.isBlank() ? "" : ": " + Text.escapeJagex(f.description.replaceAll("\\s+", " ").trim()));
				popups.add(new Popup(kind + " Complete!", text, chat, f.id.endsWith(":flip"), f.id));
				poppedAt.put(f.id, System.currentTimeMillis());
			}
		}
		// the welcome first, then tiles, then rows, then columns, queued ones too (user, 2026-11-03)
		List<Popup> queued = new ArrayList<>(popups);
		queued.sort(Comparator.comparingInt(p -> p.id == null ? 0 : p.id.startsWith("row:") ? 2 : p.id.startsWith("col:") ? 3 : p.id.startsWith("diag:") ? 4 : p.id.equals("bingo") ? 5 : 1));
		popups.clear();
		popups.addAll(queued);
		log.debug("Cabbingo: finished {}, seen before {}", ids, finishedSeen);
		if (!ids.equals(finishedSeen))
		{
			configManager.setConfiguration(CabbingoConfig.GROUP, SEEN, String.join(",", ids));
		}
		finishedSeen = ids;
	}

	private static boolean isLine(String id)
	{
		return id.startsWith("row:") || id.startsWith("col:") || id.startsWith("diag:");
	}

	// only the sides that got no popup since before: the time a post was sent
	synchronized void unsee(String[] ids, long before)
	{
		List<String> old = Arrays.stream(ids).filter(id -> poppedAt.getOrDefault(id, 0L) < before).collect(Collectors.toList());
		if (finishedSeen != null && finishedSeen.removeAll(old))
		{
			configManager.setConfiguration(CabbingoConfig.GROUP, SEEN, String.join(",", finishedSeen));
		}
	}

	// The next popup, once the game shows none: the same one the collection log uses. Once a tick.
	void tick()
	{
		if (popups.isEmpty())
		{
			popupWaiting = 0;
			return;
		}
		// one after another, each with its sound; not over the game's own popup (collection log, League task) nor behind
		// the "Click here to play" screen, nor while a bank or other window is open (it would not show, only its sound:
		// tried 2026-11-02). Only what shows counts: an interface can stay loaded once it is gone (a
		// Blast Furnace popup waited for minutes, 2026-11-02).
		long now = System.currentTimeMillis();
		String busy = popupNode != null ? "ours" : showing(InterfaceID.NotificationDisplay.CONTAINER) ? "game popup" : showing(InterfaceID.WelcomeScreen.UNIVERSE) ? "welcome screen"
			: modalOpen(client) ? "open window" : now < soundUntil ? "sound" : null;
		if (busy != null)
		{
			if (popupWaiting == 0)
			{
				popupWaiting = now;
			}
			else if (now - popupWaiting > 10_000 && (now - popupWaiting) % 10_000 < 600)
			{
				log.debug("Cabbingo: popup waits for {}", busy);
			}
			return;
		}
		popupWaiting = 0;
		Popup next = popups.poll();
		log.debug("Cabbingo: popup {}", next.text);
		int parent = !client.isResized() ? InterfaceID.Toplevel.MAINCRM
			: client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1 ? InterfaceID.ToplevelPreEoc.NOTIFICATIONS
			: InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;
		WidgetNode node = client.openInterface(parent, POPUP, WidgetModalMode.MODAL_CLICKTHROUGH);
		Widget popup = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
		client.runScript(POPUP_SCRIPT, next.title, next.text, -1);
		if (next.chat != null)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", next.chat, null);
		}
		playSound(next.flip ? config.flipSound() : config.sound());
		// closed again once it has played (or after 20 s at most), or the next one could not open
		popupNode = node;
		clientThread.invokeLater(() ->
		{
			if (popup != null && popup.getWidth() > 0 && System.currentTimeMillis() - now < 20_000)
			{
				return false;
			}
			try
			{
				client.closeInterface(node, true);
			}
			catch (IllegalArgumentException ex)
			{
				// the game closed it first ("WidgetNode is no longer valid"): nothing left to close
			}
			popupNode = null;
			return true;
		});
	}

	// a window in the middle of the screen (bank, shop, Blast Furnace bars): the game's own windows the player closes.
	// Client thread only.
	static boolean modalOpen(Client client)
	{
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getModalMode() == WidgetModalMode.MODAL_NOCLICKTHROUGH)
			{
				return true;
			}
		}
		return false;
	}

	private boolean showing(int componentId)
	{
		Widget w = client.getWidget(componentId);
		return w != null && !w.isHidden() && w.getWidth() > 0;
	}

	/** On the client thread. */
	void playSound(Sound sound)
	{
		int volume = config.volume();
		long now = System.currentTimeMillis();
		if (volume <= 0 || now < soundUntil)
		{
			return; // the last sound still plays: no pile-up from double clicks
		}
		soundUntil = now + sound.ms;
		if (sound.id > 0)
		{
			client.playSoundEffect(sound.id, volume * 127 / 100);
		}
		else if (sound.file != null)
		{
			executor.execute(() ->
			{
				try
				{
					audioPlayer.play(CabbingoPlugin.class, sound.file, 20f * (float) Math.log10(volume / 100.0));
				}
				catch (Exception ex)
				{
					log.debug("Cabbingo sound {} did not play", sound.file, ex);
				}
			});
		}
	}
}

