	// A new size keeps each tile at its row and column
	private void resize(int n)
	{
		if (n == form.size)
		{
			return;
		}
		List<Tile> tiles = new ArrayList<>();
		for (int i = 0; i < n * n; i++)
		{
			int r = i / n, c = i % n;
			tiles.add(r < form.size && c < form.size ? form.tiles.get(r * form.size + c) : null);
		}
		form.size = n;
		form.tiles = tiles;
		tileAt = -1;
	}

