	// a field and Add (Enter or a picked suggestion adds too); added answers why a name was not added, or null
	private JPanel addRow(String placeholder, Supplier<List<String>> suggestions, Function<String, String> added)
	{
		JPanel p = new JPanel(new BorderLayout(4, 0));
		p.setOpaque(false);
		JTextField f = new JTextField();
		style(f);
		f.getAccessibleContext().setAccessibleName(placeholder);
		p.add(f, BorderLayout.CENTER);
		Btn add = new Btn("Add", Color.WHITE, SURFACE, EDGE_HI);
		Runnable go = () ->
		{
			String v = f.getText().trim();
			if (v.isEmpty())
			{
				return;
			}
			String error = added.apply(v);
			if (error != null)
			{
				fail(error);
				return;
			}
			status.setText("");
			render();
		};
		add.addActionListener(e -> go.run());
		f.addActionListener(e -> go.run());
		if (suggestions != null)
		{
			Suggest.attach(f, suggestions, v ->
			{
				f.setText(v);
				go.run();
			});
		}
		p.add(add, BorderLayout.EAST);
		return p;
	}

	// A label with the site's black text shadow (one line; cut with "..." when too long)
	static class Text extends JLabel
	{
		Text(String text, Color color)
		{
			super(text);
			setForeground(color);
			setFont(FontManager.getRunescapeFont());
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			String s = getText();
			if (s == null || s.startsWith("<html>"))
			{
				super.paintComponent(g0);
				return;
			}
			Graphics2D g = (Graphics2D) g0.create();
			Insets in = getInsets();
			int x = in.left;
			Icon icon = getIcon();
			if (icon != null)
			{
				icon.paintIcon(this, g, x, (getHeight() - icon.getIconHeight()) / 2);
				x += icon.getIconWidth() + getIconTextGap();
			}
			g.setFont(getFont());
			FontMetrics fm = g.getFontMetrics();
			String t = BoardOverlay.fit(g, s, getWidth() - in.right - x);
			if (getHorizontalAlignment() == SwingConstants.RIGHT || getHorizontalAlignment() == SwingConstants.TRAILING)
			{
				x = getWidth() - in.right - fm.stringWidth(t);
			}
			int y = in.top + (getHeight() - in.top - in.bottom - fm.getHeight()) / 2 + fm.getAscent();
			BoardOverlay.shadowed(g, t, x, y, getForeground(), 1);
			g.dispose();
		}
	}

	// A button in the site's look: a fill and an edge (lighter on hover), the stone button picture for the main ones,
	// a gold outline for the picked one, shadowed text and an optional icon
	static class Btn extends JButton
	{
		Color fill;
		Color line;
		Color outline;
		BufferedImage image;

		Btn(String text, Color color, Color fill, Color line)
		{
			super(text);
			this.fill = fill;
			this.line = line;
			setForeground(color);
			setFont(FontManager.getRunescapeFont());
			setContentAreaFilled(false);
			setFocusPainted(false);
			setBorderPainted(false);
			setOpaque(false);
			setBorder(new EmptyBorder(0, 6, 0, 6));
			setRolloverEnabled(true);
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			Graphics2D g = (Graphics2D) g0.create();
			int w = getWidth(), h = getHeight();
			boolean hover = getModel().isRollover() || getModel().isPressed();
			if (image != null)
			{
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.drawImage(image, 0, 0, w, h, null);
			}
			else if (fill != null)
			{
				g.setColor(hover ? SURFACE_HI : fill);
				g.fillRect(0, 0, w, h);
			}
			if (line != null)
			{
				g.setColor(line);
				g.drawRect(0, 0, w - 1, h - 1);
			}
			if (outline != null)
			{
				g.setColor(outline);
				g.setStroke(new BasicStroke(2));
				g.drawRect(1, 1, w - 2, h - 2);
			}
			Icon icon = getIcon();
			if (icon != null)
			{
				icon.paintIcon(this, g, (w - icon.getIconWidth()) / 2, (h - icon.getIconHeight()) / 2);
			}
			// laid-out children (a card's lines) paint themselves
			String s = getText();
			if (s != null && !s.isEmpty())
			{
				g.setFont(getFont());
				FontMetrics fm = g.getFontMetrics();
				Insets in = getInsets();
				String t = BoardOverlay.fit(g, s, w - in.left - in.right);
				int x = getHorizontalAlignment() == SwingConstants.LEFT ? in.left : (w - fm.stringWidth(t)) / 2;
				int y = (h - fm.getHeight()) / 2 + fm.getAscent();
				Color color = hover && image == null && fill == null && !Color.WHITE.equals(getForeground()) ? GOLD : getForeground();
				BoardOverlay.shadowed(g, t, x, y, image != null && hover ? GOLD : color, image != null ? 2 : 1);
			}
			g.dispose();
		}

		@Override
		public Dimension getPreferredSize()
		{
			if (isPreferredSizeSet() || getComponentCount() > 0)
			{
				return super.getPreferredSize();
			}
			FontMetrics fm = getFontMetrics(getFont());
			Insets in = getInsets();
			int text = getText() == null ? 0 : fm.stringWidth(getText());
			int icon = getIcon() == null ? 0 : getIcon().getIconWidth();
			return new Dimension(Math.max(text, icon) + in.left + in.right + 2, 26);
		}
	}

	// Drawn icons: the Back chevron, the delete trashcan, a Reviewed row's closed and open arrow
	static class Glyph implements Icon
	{
		static final int BACK = 0, TRASH = 1, CLOSED = 2, OPEN = 3;
		private final int kind;
		private final Color color;

		Glyph(int kind, Color color)
		{
			this.kind = kind;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g0, int x, int y)
		{
			Graphics2D g = (Graphics2D) g0.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.translate(x, y);
			g.setColor(color);
			if (kind == BACK)
			{
				g.setStroke(new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawPolyline(new int[]{11, 5, 11}, new int[]{3, 9, 15}, 3);
			}
			else if (kind == CLOSED || kind == OPEN)
			{
				g.setStroke(new BasicStroke(2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				if (kind == CLOSED)
				{
					g.drawPolyline(new int[]{6, 11, 6}, new int[]{4, 9, 14}, 3);
				}
				else
				{
					g.drawPolyline(new int[]{4, 9, 14}, new int[]{6, 11, 6}, 3);
				}
			}
			else
			{
				g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(2, 4, 16, 4);
				g.drawRect(4, 4, 10, 12);
				g.drawLine(7, 4, 7, 2);
				g.drawLine(7, 2, 11, 2);
				g.drawLine(11, 2, 11, 4);
				g.drawLine(7, 8, 7, 13);
				g.drawLine(11, 8, 11, 13);
			}
			g.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 18;
		}

		@Override
		public int getIconHeight()
		{
			return 18;
		}
	}
}

package com.cabbingo;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.ui.FontManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Posts to the team's URL, with a screenshot when it matters. The answer says when the
 * plugin's copy of the team is out of date (X-Rev), which sides the post finished (X-Finished), and when a post
 * needed a screenshot after all (409). A screenshot never shows the split private chat: it goes to the team's
 * Discord channel (user, 2026-11-13).
 */
@Slf4j
@Singleton
class Sender
{
	private static final MediaType JSON = MediaType.parse("application/json");
	private static final MediaType JPEG = MediaType.parse("image/jpeg");
	private static final float JPEG_QUALITY = 0.85f;
	private static final DateTimeFormatter STAMP_TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss 'UTC'").withZone(ZoneOffset.UTC);
	private static final Color STAMP_BOX = new Color(0, 0, 0, 153);

	private final Client client;
	private final ClientThread clientThread;
	private final Team team;
	private final Popups popups;
	private final OkHttpClient http;
	private final Gson gson;
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	Sender(Client client, ClientThread clientThread, Team team, Popups popups, OkHttpClient http, Gson gson, DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.team = team;
		this.popups = popups;
		this.http = http;
		this.gson = gson;
		this.drawManager = drawManager;
		this.executor = executor;
	}

	// The drop worker's post shape; Discord shows content and ignores the rest.
	static JsonObject payload(String type, String rsn, String content, JsonObject extra)
	{
		JsonObject p = new JsonObject();
		p.addProperty("type", type);
		p.addProperty("playerName", rsn);
		p.addProperty("content", content);
		p.add("embeds", new JsonArray());
		p.add("extra", extra);
		return p;
	}

	void send(JsonObject payload, boolean shot)
	{
		HttpUrl url = team.url();
		if (url == null)
		{
			return;
		}
		if (!shot)
		{
			post(url, RequestBody.create(JSON, gson.toJson(payload)), payload);
			return;
		}
		// on the client thread (a post's 409 answer asks from OkHttp's): the private chat is hidden for the one frame taken
		clientThread.invoke(() ->
		{
			Widget pm = client.getWidget(InterfaceID.PmChat.CONTAINER);
			boolean hide = pm != null && !pm.isHidden();
			if (hide)
			{
				pm.setHidden(true);
			}
			drawManager.requestNextFrameListener(frame ->
			{
				Wants w = team.wants();
				String title = stampTitle(w == null ? null : w.name);
				String time = STAMP_TIME.format(Instant.now());
				if (hide)
				{
					clientThread.invoke(() -> pm.setHidden(false));
				}
				executor.execute(() ->
				{
					MultipartBody.Builder body = new MultipartBody.Builder().setType(MultipartBody.FORM)
						.addFormDataPart("payload_json", gson.toJson(payload));
					try
					{
						body.addFormDataPart("file", "screenshot.jpg", RequestBody.create(JPEG, jpeg(frame, title, time)));
					}
					catch (IOException e)
					{
						log.debug("Cabbingo: no screenshot", e);
					}
					post(url, body.build(), null);
				});
			});
		});
	}

	// again: the post without a screenshot, sent once more with one when the server asks for it (409)
	private void post(HttpUrl url, RequestBody body, JsonObject again)
	{
		Request request = new Request.Builder().url(url).post(body).build();
		long sent = System.currentTimeMillis();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cabbingo: post failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					// The board changed since this plugin's copy of it: ask for the new one now, not at the next poll.
					String rev = response.header("X-Rev");
					Wants w = team.wants();
					log.debug("Cabbingo: post answered {}, rev {} (had {})", response.code(), rev, w == null ? null : w.rev);
					// sides this post finished: news even when this plugin still had them as finished
					String added = response.header("X-Finished");
					if (added != null)
					{
						// the answer carries the team's finished list: the popup comes now, not after another fetch
						// (an older server sends none, and the fetch below brings it)
						List<Finished> finished = null;
						try
						{
							Wants f = gson.fromJson(response.body().charStream(), Wants.class);
							finished = f == null ? null : f.finished;
						}
						catch (RuntimeException e)
						{
							log.debug("Cabbingo: no finished list in the answer", e);
						}
						List<Finished> list = finished;
						clientThread.invoke(() ->
						{
							popups.unsee(added.split(","), sent);
							if (list != null && !list.isEmpty())
							{
								popups.finished(list);
							}
						});
					}
					if (rev != null && w != null && (!rev.equals(w.rev) || added != null))
					{
						w.rev = rev; // (one ask, not one per post while it is on its way)
						team.fetch();
					}
					// The server knows this drop needed a screenshot (a tile item the copy did not have yet). The loot is
					// still on the screen a moment after the kill.
					if (response.code() == 409 && again != null)
					{
						send(again, true);
					}
				}
			}
		});
	}

	// the bingo's title, cut at 20 characters so the stamp hides little of the game (user, 2026-11-27)
	static String stampTitle(String title)
	{
		String t = title == null ? "" : title.trim();
		return t.length() > 20 ? t.substring(0, 20).trim() : t;
	}

	// The stamp on every screenshot (picked 2026-11-27, canvas ShotStamp B): top centre, 8 px down, white Runescape bold
	// at its own 16 px without smoothing (sharp; 20 px read soft), 1 px black shadow, on a box of black at 60%, 10 px side
	// padding, 4 px corners. Title and time apart by the width of " - ", without the dash; only the time with no title.
	static void stamp(Graphics2D g, int width, String title, String time)
	{
		g.setFont(FontManager.getRunescapeBoldFont());
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		FontMetrics fm = g.getFontMetrics();
		int gap = title.isEmpty() ? 0 : fm.stringWidth(title) + fm.stringWidth(" - ");
		int w = gap + fm.stringWidth(time) + 20;
		int h = fm.getHeight() + 6;
		int x = (width - w) / 2;
		int y = 8;
		g.setColor(STAMP_BOX);
		g.fillRoundRect(x, y, w, h, 8, 8);
		int ty = y + 3 + fm.getAscent();
		shadowed(g, title, x + 10, ty);
		shadowed(g, time, x + 10 + gap, ty);
	}

	private static void shadowed(Graphics2D g, String text, int x, int y)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(Color.WHITE);
		g.drawString(text, x, y);
	}

	// JPEG instead of PNG: about 200 KB for a game screenshot instead of 1.5 to 2 MB.
	private static byte[] jpeg(Image frame, String title, String time) throws IOException
	{
		BufferedImage rgb = new BufferedImage(frame.getWidth(null), frame.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = rgb.createGraphics();
		g.drawImage(frame, 0, 0, null);
		stamp(g, rgb.getWidth(), title, time);
		g.dispose();
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		ImageWriteParam param = writer.getDefaultWriteParam();
		param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
		param.setCompressionQuality(JPEG_QUALITY);
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (ImageOutputStream stream = ImageIO.createImageOutputStream(out))
		{
			writer.setOutput(stream);
			writer.write(null, new IIOImage(rgb, null, null), param);
		}
		finally
		{
			writer.dispose();
		}
		return out.toByteArray();
	}
}

package com.cabbingo;

import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

// What a player gathered or made per skill until the next send, for Skilling tiles (2026-11-01).
// Woodcutting and Fishing count from the game's message ("You get some yew logs."), as RuneLite's own Woodcutting
// plugin does: logs and fish that go into a log basket or fish barrel never reach the backpack. Every other skill
// counts what the backpack gained in a tick that gave that skill XP. Gems that go into an open gem bag count from the
// message that named them just before (2026-11-02, messages as other Plugin Hub plugins read them). Herbs that go into
// an open herb sack come with no message at all (tried in the game 2026-11-02): the plugin counts them from the patch
// (herbAt).
class SkillCounter
{
	// the same list as SKILLING in Cabbingo's models/bingo.ts
	static final List<String> SKILLS = Arrays.asList(
		"Cooking", "Crafting", "Farming", "Fishing", "Fletching", "Herblore", "Hunter", "Mining", "Runecraft", "Smithing", "Woodcutting");
	private static final List<String> BY_MESSAGE = Arrays.asList("Woodcutting", "Fishing");
	private static final Pattern LOGS = Pattern.compile("You get (?:some|an?) ((?:[\\w' -]+ )?logs?)\\.");
	// "You catch a shark!", and since 2026-11-02 also "You catch a raw trout" (no stop, the item's own name)
	private static final Pattern FISH = Pattern.compile("You catch (an?|some|\\d+) ([\\w' -]+?)[.!]?");
	private static final Pattern GEM = Pattern.compile("You just (?:mined|found) (?:a piece of|an?) ([\\w ]+)!");
	// "You put it into your gem bag." (tried in the game 2026-11-02), "... straight into your open gem bag." (other plugins); the gem
	// sack takes opal, jade and red topaz too (user, 2026-11-02)
	private static final Pattern GEM_BAG = Pattern.compile("You put it (?:straight )?into your (?:open )?gem (?:bag|sack)\\.");

	private final Map<String, Map<String, Integer>> counts = new LinkedHashMap<>();
	// What Skilling tiles want, from the server: groups of items (lower case) and how many more of them, mixed, finish
	// a side (0: never on their own). The counts go out two minutes after the last wanted item, not at the next batch, and
	// at once when a group has its number (2026-11-03).
	// marks: the counts still to go at which a screenshot goes along, at 25, 50, 75 and 100% of the group (2026-11-04):
	// the proof of a tile only the plugin counts. The send goes out at once then too.
	static class Goal
	{
		String id; // the side's, for the board window's live count (an older server sends none)
		Set<String> items = new HashSet<>();
		int left;
		int[] marks;
	}

	private volatile List<Goal> goals = Collections.emptyList();
	// what a counted item shows on the board window at once (side id, quantity): the server confirms it with the send
	interface Live
	{
		void counted(String sideId, int quantity, String item);
	}

	private volatile Live live = (id, n, item) -> { };

	void live(Live live)
	{
		this.live = live;
	}
	// Sent since the server's goals last changed: it renews them only when a side finishes, so after a send that
	// finished nothing its numbers still count those items as missing (21 of 30 logs sent, 2026-11-02).
	private final Map<String, Integer> sent = new HashMap<>();
	private String goalsRev;

	synchronized void goals(List<Goal> goals, String rev)
	{
		if (!Objects.equals(rev, goalsRev))
		{
			sent.clear();
			goalsRev = rev;
		}
		this.goals = goals;
	}
	private long wantedAt;
	private boolean finishes;
	// the gem the message before named, for the gem bag message right after it
	private String gem;
	// the fish last caught: an extra one (Rada's blessing and the like) does not say which (tried in the game 2026-11-02)
	private String fish;

	synchronized void add(String skill, String item, int quantity)
	{
		String key = item.toLowerCase(Locale.ROOT);
		Map<Goal, Integer> before = new HashMap<>();
		for (Goal goal : goals)
		{
			if (goal.items.contains(key))
			{
				before.put(goal, counted(goal.items));
			}
		}
		counts.computeIfAbsent(skill, s -> new LinkedHashMap<>()).merge(item, quantity, Integer::sum);
		before.forEach((goal, had) ->
		{
			if (goal.id != null)
			{
				live.counted(goal.id, quantity, item);
			}
			wantedAt = System.currentTimeMillis();
			int now = counted(goal.items);
			finishes |= goal.left > 0 && now >= goal.left;
			for (int mark : goal.marks == null ? new int[0] : goal.marks)
			{
				if (had < goal.left - mark && now >= goal.left - mark)
				{
					shots.add(skill);
				}
			}
		});
	}

	// The skills whose next send takes a screenshot along (a mark was reached); empty again afterwards.
	private final Set<String> shots = new HashSet<>();

	synchronized Set<String> takeShots()
	{
		Set<String> taken = new HashSet<>(shots);
		shots.clear();
		return taken;
	}

	private int counted(Set<String> items)
	{
		int sum = 0;
		for (Map.Entry<String, Integer> e : sent.entrySet())
		{
			sum += items.contains(e.getKey()) ? e.getValue() : 0;
		}
		for (Map<String, Integer> skill : counts.values())
		{
			for (Map.Entry<String, Integer> e : skill.entrySet())
			{
				sum += items.contains(e.getKey().toLowerCase(Locale.ROOT)) ? e.getValue() : 0;
			}
		}
		return sum;
	}

	// A side's last item, a mark, or WAIT without a new wanted item since the last one: time to send. Two minutes (was
	// one): each post that counts syncs the whole team (2026-11-12).
	static final long WAIT = 120_000;

	synchronized boolean due(long now)
	{
		return finishes || !shots.isEmpty() || (wantedAt > 0 && now - wantedAt >= WAIT);
	}

	// A game message that names a log, fish or bagged gem: counted, true.
	boolean message(String text)
	{
		String named = gem;
		gem = null;
		Matcher m = GEM.matcher(text);
		if (m.matches())
		{
			gem = "Uncut " + m.group(1).toLowerCase(Locale.ROOT);
			return false; // a gem in the backpack counts from there
		}
		if (named != null && GEM_BAG.matcher(text).matches())
		{
			add("Mining", named, 1);
			return true;
		}
		m = LOGS.matcher(text);
		if (m.matches())
		{
			add("Woodcutting", capitalize(m.group(1)), 1);
			return true;
		}
		m = FISH.matcher(text);
		if (m.matches())
		{
			String caught = m.group(2).toLowerCase(Locale.ROOT);
			int quantity = m.group(1).matches("\\d+") ? Integer.parseInt(m.group(1)) : 1;
			// (barbarian fishing's leaping fish have no "Raw" in their name)
			fish = caught.startsWith("leaping ") || caught.startsWith("raw ") ? capitalize(caught) : "Raw " + caught;
			add("Fishing", fish, quantity);
			return true;
		}
		// "Rada's blessing enabled you to catch an extra fish."
		if (text.endsWith(" enabled you to catch an extra fish.") && fish != null)
		{
			add("Fishing", fish, 1);
			return true;
		}
		return false;
	}

	// The backpack's gains around a tick with XP in these skills: counted for the first of them that counts from the
	// backpack. Woodcutting and Fishing count from their messages instead, so never twice.
	void gained(Collection<String> skills, Map<String, Integer> items)
	{
		for (String skill : SKILLS)
		{
			if (skills.contains(skill) && !BY_MESSAGE.contains(skill))
			{
				items.forEach((name, quantity) -> add(skill, name, quantity));
				return;
			}
		}
	}

	// A herb patch's varbit value while it has herbs to pick: the grimy herb it gives, else null. The ranges are
	// RuneLite's own (Time Tracking's PatchImplementation.HERB): each herb has three harvestable values.
	private static final int[] HERB_VALUES = {8, 15, 22, 29, 36, 43, 50, 57, 64, 72, 79, 86, 93, 100, 107};
	private static final String[] HERBS = {"guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed", "toadflax", "irit leaf",
		"avantoe", "huasca", "kwuarm", "snapdragon", "cadantine", "lantadyme", "dwarf weed", "torstol"};

	static String herbAt(int value)
	{
		for (int i = 0; i < HERB_VALUES.length; i++)
		{
			if (value >= HERB_VALUES[i] && value <= HERB_VALUES[i] + 2)
			{
				return "Grimy " + HERBS[i];
			}
		}
		return null;
	}

	// Everything counted since the last call, per skill; empty again afterwards.
	synchronized Map<String, Map<String, Integer>> take()
	{
		Map<String, Map<String, Integer>> taken = new LinkedHashMap<>(counts);
		taken.values().forEach(items -> items.forEach((name, n) -> sent.merge(name.toLowerCase(Locale.ROOT), n, Integer::sum)));
		counts.clear();
		wantedAt = 0;
		finishes = false;
		return taken;
	}

	static String capitalize(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1).toLowerCase(Locale.ROOT);
	}
}

package com.cabbingo;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
