package com.cabbingo;

import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/**
 * Suggestions under a text field while typing, as the site's tile editor has (SelfPanel: item names from the game,
 * bosses from the hiscores): names that start with the text first, then names that hold it, at most 8.
 */
final class Suggest
{
	private static final int MAX = 8;
	private static final String PICKED = "cabbingo.suggestPicked";

	private Suggest()
	{
	}

	static void attach(JTextField field, Supplier<List<String>> names, Consumer<String> picked)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setFocusable(false); // (the typing stays in the field)
		menu.setBackground(SelfPanel.SURFACE);
		menu.setBorder(javax.swing.BorderFactory.createLineBorder(SelfPanel.EDGE_HI));
		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				SwingUtilities.invokeLater(() -> show(field, menu, names.get(), picked));
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				SwingUtilities.invokeLater(() -> show(field, menu, names.get(), picked));
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
			}
		});
		field.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				menu.setVisible(false);
			}
		});
	}

	private static void show(JTextField field, JPopupMenu menu, List<String> names, Consumer<String> picked)
	{
		menu.setVisible(false);
		menu.removeAll();
		String q = field.getText().trim().toLowerCase(Locale.ROOT);
		// (the picked name set into the field does not open the list again)
		if (q.length() < 2 || !field.isFocusOwner() || q.equalsIgnoreCase(String.valueOf(field.getClientProperty(PICKED))))
		{
			return;
		}
		List<String> found = Stream.concat(
			names.stream().filter(n -> n.toLowerCase(Locale.ROOT).startsWith(q)),
			names.stream().filter(n -> !n.toLowerCase(Locale.ROOT).startsWith(q) && n.toLowerCase(Locale.ROOT).contains(q))
		).limit(MAX).collect(Collectors.toList());
		// a full name keeps the longer ones in view ("Chinchompa": Red chinchompa, Black chinchompa); only the name itself left closes it
		if (found.isEmpty() || found.size() == 1 && found.get(0).equalsIgnoreCase(q))
		{
			return;
		}
		for (String name : found)
		{
			JMenuItem item = new JMenuItem(name);
			item.setBackground(SelfPanel.SURFACE);
			item.setForeground(java.awt.Color.WHITE);
			item.addActionListener(e ->
			{
				menu.setVisible(false);
				field.putClientProperty(PICKED, name);
				picked.accept(name);
			});
			menu.add(item);
		}
		menu.show(field, 0, field.getHeight());
	}
}

package com.cabbingo;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/**
 * The player's team on the server: the Team URL, what the team wants (GET /plugin/key) and the live line that says
 * when to ask again. Each answer goes to the plugin (onWants), on the client thread: the popups, the board window
 * and the goals are all changed there, never by two answers at once (a welcome showed twice, a popup could too).
 */
@Slf4j
@Singleton
class Team
{
	static final long HOUR = 60 * 60 * 1000L;

	private final Client client;
	private final ClientThread clientThread;
	private final CabbingoConfig config;
	private final OkHttpClient http;
	private final Gson gson;

	// What the team wants, from the server. Null until it answered (no key, a wrong key, offline).
	private volatile Wants wants;
	private volatile Consumer<Wants> onWants = w -> { };
	// The team's live line (the server's TeamPush): "finished" when the team finishes a side, so a teammate's popup comes
	// at once (user, 2026-11-02). Open while logged in during the bingo; the minute poll stays for when it is down.
	private OkHttpClient pushHttp;
	private volatile WebSocket push;
	private long pushAgain; // the next try after it dropped or could not open
	private long pushWait = 60_000; // doubles per failed try, up to half an hour
	// The poll, for what the live line (openPush) does not bring: every minute while it is down, so a finish still pops
	// up within a minute; every 5 minutes while it is up (it brings finishes and board changes); every 30 minutes outside
	// the bingo (a date can still move); never for a key the server no longer knows, until a login or another URL asks.
	// It was every minute always, ~1.5k requests a day per logged-in player, also long after the bingo (2026-11-12).
	private volatile long lastFetch;
	private volatile boolean gone;
	volatile boolean offTeamTold; // the off-team chat line was shown this login (Wants.offTeam)
	volatile boolean nameSent; // a fetch this login sent the player's name: the server could say offTeam
	// the Team URL and name the server last said are on the team during the bingo: no off-team check for them again
	// (user, 2026-11-24); null for none
	private volatile String onTeam;

	@Inject
	Team(Client client, ClientThread clientThread, CabbingoConfig config, OkHttpClient http, Gson gson)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.http = http;
		this.gson = gson;
	}

	Wants wants()
	{
		return wants;
	}

	/** Where each answer goes; null for none (the plugin is off), or an older one to forget. */
	void onWants(Consumer<Wants> onWants)
	{
		this.onWants = onWants;
	}

	void clear()
	{
		wants = null;
	}

	boolean inBingo()
	{
		Wants w = wants;
		long now = System.currentTimeMillis();
		return w != null && now >= w.start - HOUR && now <= w.end + HOUR;
	}

	// Whether a TempleOSRS tile will count what this player gains now: the bingo has started and the player is on the
	// team. Not the hour before the start that playing() allows: TempleOSRS counts from the start only.
	boolean templeCounts()
	{
		Wants w = wants;
		return w != null && System.currentTimeMillis() >= w.start && !w.offTeam;
	}

	// The local player's name from an hour before the bingo to an hour after it, else null. The server checks the team and
	// the exact dates on every post, as they are at that moment, and ignores a kill outside them: a player added to the
	// team never loses a kill to this plugin's older copy, and the hour covers a date change until the next refresh.
	String playing()
	{
		if (!inBingo() || client.getLocalPlayer() == null)
		{
			return null;
		}
		return name(client.getLocalPlayer().getName());
	}

	// (the game puts a no-break space in some names; the server and the team list use a plain one)
	static String name(String rsn)
	{
		return rsn != null ? rsn.replace(' ', ' ') : null;
	}

	// The URL the player pasted, like a webhook: this plugin sends nowhere else. Null when it is
	// empty or not a URL.
	HttpUrl url()
	{
		return HttpUrl.parse(config.url().trim());
	}

	// Tiles of the day and team changes reach the plugin through the live line, else this poll (once a minute).
	void poll()
	{
		if (client.getGameState() != GameState.LOGGED_IN || gone)
		{
			return;
		}
		Wants w = wants;
		long now = System.currentTimeMillis();
		boolean during = w == null || (now >= w.start - HOUR && now <= w.end + 24 * HOUR);
		long every = !during ? 30 * 60_000 : push != null ? 5 * 60_000 : 60_000;
		// (a few seconds early: the schedule and the last answer drift a little)
		if (now - lastFetch >= every - 5_000)
		{
			fetch();
		}
	}

	// The fetch at login comes before the player is in the world, so without the name: once the name is there it asks
	// again, and the off-team warning shows at login, not at the next poll minutes later (user, 2026-11-24). Each tick.
	void sendName()
	{
		Player me = client.getLocalPlayer();
		HttpUrl url = nameSent || gone || me == null || me.getName() == null ? null : url();
		if (url == null)
		{
			return;
		}
		if ((url + "|" + name(me.getName())).equals(onTeam))
		{
			nameSent = true; // known to be on the team: nothing to check
			return;
		}
		fetch();
	}

	void fetch()
	{
		HttpUrl url = url();
		if (url == null)
		{
			wants = null;
			clientThread.invoke(() -> onWants.accept(null));
			return;
		}
		// never into RuneLite's disk cache: two clients on one computer asking at the same moment (a live line's
		// "finished") failed to rename the same cache file, and that answer was lost (2026-11-03)
		// the player's name: the server says when it is not on the team's list (null before the player is in the
		// world: sendName asks again once it is there)
		Player me = client.getLocalPlayer(); // (once: fetch runs off the client thread, the player can go at logout)
		String rsn = me == null ? null : name(me.getName());
		nameSent |= rsn != null;
		String asked = rsn == null ? null : url + "|" + rsn;
		if (rsn != null)
		{
			url = url.newBuilder().addQueryParameter("rsn", rsn).build();
		}
		Request request = new Request.Builder().url(url).cacheControl(new CacheControl.Builder().noStore().build()).build();
		lastFetch = System.currentTimeMillis();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cabbingo: no team settings", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					Wants w = response.isSuccessful() ? gson.fromJson(response.body().charStream(), Wants.class) : null;
					gone = response.code() == 404; // the team's key is gone: no more polls
					long now = System.currentTimeMillis();
					if (w != null && asked != null && now >= w.start && now <= w.end)
					{
						onTeam = w.offTeam ? null : asked;
					}
					clientThread.invoke(() ->
					{
						wants = w;
						onWants.accept(w);
						// nothing this account does counts: said once a login
						if (w != null && w.offTeam && !offTeamTold)
						{
							offTeamTold = true;
							client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
								"<col=ef1020>Cabbingo: this account is not on your team's player list. Its kills, drops and XP do not count until the bingo owner adds it.</col>", null);
						}
					});
				}
			}
		});
	}

	/** Another team's board (a click on it in the window's Standings), handed to done on the client thread; null when there is none. */
	void board(String teamId, Consumer<BoardOverlay.Board> done)
	{
		HttpUrl url = url();
		if (url == null)
		{
			clientThread.invoke(() -> done.accept(null));
			return;
		}
		Request request = new Request.Builder().url(url.newBuilder().addPathSegment("board").addPathSegment(teamId).build())
			.cacheControl(new CacheControl.Builder().noStore().build()).build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cabbingo: no board of team {}", teamId, e);
				clientThread.invoke(() -> done.accept(null));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					BoardOverlay.Board b = response.isSuccessful() ? gson.fromJson(response.body().charStream(), BoardOverlay.Board.class) : null;
					clientThread.invoke(() -> done.accept(b));
				}
				catch (RuntimeException e)
				{
					log.debug("Cabbingo: bad board of team {}", teamId, e);
					clientThread.invoke(() -> done.accept(null));
				}
			}
		});
	}

	synchronized void openPush()
	{
		long now = System.currentTimeMillis();
		HttpUrl url = url();
		if (push != null || now < pushAgain || url == null)
		{
			return;
		}
		if (pushHttp == null)
		{
			pushHttp = http.newBuilder().pingInterval(30, TimeUnit.SECONDS).build();
		}
		Request request = new Request.Builder().url(url.newBuilder().addPathSegment("push").build()).build();
		push = pushHttp.newWebSocket(request, new WebSocketListener()
		{
			@Override
			public void onOpen(WebSocket ws, Response response)
			{
				pushWait = 60_000;
			}

			@Override
			public void onMessage(WebSocket ws, String text)
			{
				if ("finished".equals(text) || "board".equals(text))
				{
					fetch();
				}
			}

			@Override
			public void onClosed(WebSocket ws, int code, String reason)
			{
				dropped(ws);
			}

			@Override
			public void onFailure(WebSocket ws, Throwable t, Response response)
			{
				log.debug("Cabbingo: live line dropped", t);
				dropped(ws);
			}
		});
	}

	private synchronized void dropped(WebSocket ws)
	{
		if (push == ws)
		{
			push = null;
			pushAgain = System.currentTimeMillis() + pushWait;
			pushWait = Math.min(pushWait * 2, 30 * 60_000);
		}
	}

	synchronized void closePush()
	{
		if (push != null)
		{
			push.close(1000, null);
			push = null;
		}
		pushAgain = 0;
	}
}

package com.cabbingo;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.util.ColorUtil;

// The tile infobox: a board tile's progress while the board is closed (BoardOverlay.box). Reads the tile anew on every
// draw, so board updates show without a new box.
class TileBox extends InfoBox
{
	private static final Color GREEN = new Color(0, 200, 83);
	private static final char BULLET = 0x2022; // (not in the source as is: the build's encoding may not be UTF-8)
	private static final Color LABEL = Color.YELLOW; // as Hunter Rumours' tooltip
	final String id;
	private final BoardOverlay board;

	TileBox(BufferedImage image, Plugin plugin, String id, BoardOverlay board)
	{
		super(image, plugin);
		this.id = id;
		this.board = board;
	}

	@Override
	public String getText()
	{
		BoardOverlay.Tile t = board.tile(id);
		if (t == null || t.need == 0 && !t.done)
		{
			return "";
		}
		if (t.done)
		{
			return "Done";
		}
		// what is still to go, like Hunter Rumours' box; the tooltip has the rest (user, 2026-11-21)
		return BoardOverlay.count(left(t));
	}

	private static double left(BoardOverlay.Tile t)
	{
		return Math.max(0, t.need - t.have);
	}

	@Override
	public Color getTextColor()
	{
		BoardOverlay.Tile t = board.tile(id);
		return t != null && t.done ? GREEN : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		BoardOverlay.Tile t = board.tile(id);
		if (t == null)
		{
			return null;
		}
		// the tile's main information, each line under a coloured label like Hunter Rumours' tooltip (user, 2026-11-21)
		StringBuilder s = new StringBuilder();
		line(s, "Tile", t.title == null ? "" : t.title);
		line(s, "Points", BoardOverlay.number(t.points));
		if (progress(t))
		{
			line(s, t.counts == null ? "Progress" : t.counts, BoardOverlay.number(t.have) + " / " + BoardOverlay.number(t.need));
		}
		if (t.items != null && !t.items.isEmpty())
		{
			line(s, "Items", "");
			for (BoardOverlay.Wanted w : t.items)
			{
				s.append("</br>  ").append(BULLET).append(' ').append(w.name).append(" (").append(BoardOverlay.number(w.have))
					.append(w.need == null ? "" : " / " + BoardOverlay.number(w.need)).append(')');
			}
		}
		return s.toString();
	}

	// The tile's own "have / need" line: not when its items each show their own number, which say the same (user,
	// 2026-11-21); a tile of any N of its items keeps it, its items have no number of their own
	static boolean progress(BoardOverlay.Tile t)
	{
		return t.need > 0 && (t.items == null || t.items.isEmpty() || t.items.stream().anyMatch(w -> w.need == null));
	}

	private static void line(StringBuilder s, String label, String value)
	{
		if (s.length() > 0)
		{
			s.append("</br>");
		}
		s.append(ColorUtil.wrapWithColorTag(label + ":", LABEL)).append(' ').append(value);
	}
}

package com.cabbingo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The tile text panel: the followed tile (BoardOverlay.follow) as text, the way Quest Helper shows its step. Title,
 * points, progress with what it counts, each item, the description and the rules. A RuneLite overlay: Alt-drag moves it.
 */
@Singleton
class TilePanel extends OverlayPanel
{
	private static final Color GREEN = new Color(0, 200, 83);
	private static final Color LABEL = Color.YELLOW; // as the tile infobox's tooltip (TileBox)
	private static final String BULLET = (char) 0x2022 + " "; // (not in the source as is: the build's encoding may not be UTF-8)
	private final BoardOverlay board;
	private final CabbingoConfig config;

	@Inject
	TilePanel(BoardOverlay board, CabbingoConfig config)
	{
		this.board = board;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(200, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		BoardOverlay.Tile t = config.tilePanel() ? board.followedTile() : null;
		if (t == null)
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder().text(t.title == null ? "" : t.title).color(t.done ? GREEN : Color.ORANGE).build());
		// yellow labels, white values, lists as bullets: the tile infobox's tooltip scheme (user, 2026-11-21)
		line("Points:", BoardOverlay.number(t.points), LABEL);
		if (TileBox.progress(t))
		{
			line((t.counts == null ? "Progress" : t.counts) + ":", BoardOverlay.number(t.have) + " / " + BoardOverlay.number(t.need), LABEL);
		}
		if (t.items != null && !t.items.isEmpty())
		{
			line("Items:", "", LABEL);
			for (BoardOverlay.Wanted w : t.items)
			{
				line(BULLET + w.name, BoardOverlay.number(w.have) + (w.need == null ? "" : " / " + BoardOverlay.number(w.need)), Color.WHITE);
			}
		}
		if (t.description != null && !t.description.isEmpty())
		{
			line("Description:", "", LABEL);
			line(t.description, "", Color.WHITE);
		}
		if (t.rules != null && !t.rules.isEmpty())
		{
			line("Rules:", "", LABEL);
			for (String r : t.rules)
			{
				line(BULLET + r, "", Color.WHITE);
			}
		}
		return super.render(g);
	}

	private void line(String left, String right, Color color)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).leftColor(color).right(right).build());
	}
}

package com.cabbingo;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** The server's GET /plugin/key answer. Names and sources in lower case. */
class Wants
{
	long start;
	long end;
	boolean offTeam; // the bingo runs and the logged-in player is not on the team's list (Team.fetch sends the name)
	String name; // the bingo's title
	String mode; // the game mode; none (an older server) is Bingo
	Set<String> items = new HashSet<>();
	// the items of open Skilling sides, in groups with how many more finish a side (SkillCounter.Goal). Only skill
	// counts go to them, never a kill (2026-11-03).
	List<SkillCounter.Goal> skill = new ArrayList<>();
	Set<String> uniques = new HashSet<>(); // every boss's uniques: a kill with one never joins a batch
	Map<String, Double> sources;
	double big;
	List<Finished> finished = new ArrayList<>(); // the tile sides the team finished
	List<KillRules.Goal> kc = new ArrayList<>(); // kill count sides still open, with their food rules (2026-11-06)
	List<KillRules.Event> events = new ArrayList<>(); // the team's random events with gear or inventory rules (2026-11-07)
	// a self-hosted bingo's open XP tiles the plugin counts (none while TempleOSRS counts them, 2026-11-15)
	List<Skilling.XpGoal> xp = new ArrayList<>();
	BoardOverlay.Board board; // the in-game board; null for snakes and ladders or an older server (2026-11-12)
	String rev; // the server's fingerprint of all this; every post's answer carries the current one (X-Rev)
}

/** A tile side, row, column or diagonal the team finished (Wants.finished). */
class Finished
{
	String id;
	String title;
	int points; // what it gives: a flipped side the tile's double, a row or column its bonus
	String description;
	boolean wait; // only drops that wait for a captain's approval finish it
}

