			{"Your Barrows chest count is: 40.", "Barrows Chests"},
			{"Your Lunar Chest count is: 7.", "Lunar Chests"},
			{"Your Gauntlet completion count is: 3.", "The Gauntlet"},
			{"Your Corrupted Gauntlet completion count is: 3.", "The Corrupted Gauntlet"},
