			{"Your completed Tombs of Amascut: Expert Mode count is: 5.", "Tombs of Amascut Expert"},
			{"Your completed Chambers of Xeric count is: 12.", "Chambers of Xeric"},
			{"Your subdued Wintertodt count is: 9.", "Wintertodt"},
			{"Your TzTok-Jad kill count is: 1.", "TzTok-Jad"},
