	// the picture box drawTile gives a tile of this size
	private static double stepAt(int size)
	{
		int p = size >= 40 ? 4 : 2, bar = Math.max(p, size / 12);
		return BoardOverlay.step(size - 2 * p, size - bar - 2 * p - 2);
	}

	@Test
	public void iconSteps()
	{
		// one scale for all icons, jumping between sharp steps by tile size
		assertEquals(2, stepAt(96), 0);
		assertEquals(2, stepAt(80), 0);
		assertEquals(1, stepAt(79), 0);
		assertEquals(1, stepAt(46), 0);
		assertEquals(0.75, stepAt(45), 0);
		assertEquals(0.75, stepAt(32), 0);
		assertEquals(0.5, stepAt(31), 0);
		assertEquals(0.5, stepAt(24), 0);
		assertEquals(0.25, stepAt(16), 0); // fits the box: 12 x 8
	}

	private static BoardOverlay.Board board(double have, double item)
	{
		BoardOverlay.Board b = new BoardOverlay.Board();
		BoardOverlay.Tile t = new BoardOverlay.Tile();
		t.id = "a";
		t.have = 0;
		b.tiles.add(t);
		BoardOverlay.Tile u = new BoardOverlay.Tile();
		u.id = "b";
		u.have = have;
		BoardOverlay.Wanted w = new BoardOverlay.Wanted();
		w.name = "Dragon pickaxe";
		w.have = item;
		u.items = java.util.List.of(w);
		b.tiles.add(u);
		return b;
	}

	@Test
	public void roseFindsTheTileInProgress()
	{
		assertNull(BoardOverlay.rose(null, board(1, 0)));
		assertNull(BoardOverlay.rose(board(1, 0), board(1, 0)));
		assertEquals("b", BoardOverlay.rose(board(1, 0), board(2, 0)));
		assertEquals("b", BoardOverlay.rose(board(1, 0), board(1, 1)));
		assertNull(BoardOverlay.rose(board(2, 1), board(1, 0)));
	}

	@Test
	public void otherSideOfAFlip()
	{
		assertEquals("a:flip", BoardOverlay.otherSide("a"));
		assertEquals("a", BoardOverlay.otherSide("a:flip"));
	}

	@Test
	public void buttonIconFit()
	{
		assertEquals(1, BoardButton.fit(28 / 22.0), 0);
		assertEquals(2, BoardButton.fit(2.1), 0);
		assertEquals(0.75, BoardButton.fit(0.9), 0);
		assertEquals(0.4, BoardButton.fit(0.4), 0);
	}

	@Test
	public void progressLineOnlyWhenItemsDoNotSayIt()
	{
		BoardOverlay.Tile t = board(0, 0).tiles.get(1);
		t.need = 5;
		assertTrue(TileBox.progress(t)); // any 5 of its items: the item has no number of its own
		t.items.get(0).need = 5.0;
		assertFalse(TileBox.progress(t)); // the item shows 0 / 5 itself
		t.items = null;
		assertTrue(TileBox.progress(t)); // an XP or kill count tile
	}
}

